"use strict";
/* 一般常識 追加問題(X8/XT8/XS8)。ID恒久。 */
(window.QPARTS = window.QPARTS || []).push(
 {id:"X8-001",s:8,q:"労働契約法上の「労働者」とは、使用者に使用されて労働し、賃金を支払われる者をいい、労働基準法と異なり「事業に使用される」ことは要件とされていない。",a:true,e:"労契法2条1項。労基法9条の「事業に使用される」要件がないため、労基法の労働者より範囲が広くなり得る。",topic:"労働契約法"},
 {id:"X8-002",s:8,q:"労働契約法は、国家公務員及び地方公務員についても適用される。",a:false,e:"労契法21条1項により国家公務員・地方公務員には適用されない。同居の親族のみを使用する場合の労働契約も適用除外(同条2項)。",topic:"労働契約法"},
 {id:"X8-003",s:8,q:"労働契約は、労働者が使用者に使用されて労働し、使用者がこれに対して賃金を支払うことについて合意することによって成立し、書面の作成は成立要件ではない。",a:true,e:"労契法6条。合意のみで成立する諾成契約。書面による確認は4条2項の「できる限り」の努力にとどまる。",topic:"労働契約法"},
 {id:"X8-004",s:8,q:"労働契約において就業規則の内容と異なる労働条件を合意していた部分は、その合意が就業規則で定める基準を上回るものであっても、就業規則の基準によるものとされる。",a:false,e:"労契法7条ただし書。基準を上回る個別合意が優先する。基準に達しない部分は12条により無効となり就業規則の基準による。",topic:"労働契約法"},
 {id:"X8-005",s:8,q:"法令又は労働協約に反する就業規則の部分については、当該法令又は労働協約の適用を受ける労働者との間の労働契約に、労働契約法7条、10条及び12条の規定は適用されない。",a:true,e:"労契法13条。法令・労働協約に反する就業規則は、契約内容の補充・変更・最低基準の効力を持たない。",topic:"労働契約法"},
 {id:"X8-006",s:8,q:"使用者は、期間の定めのある労働契約について、やむを得ない事由がある場合でなければ、その契約期間が満了するまでの間において、労働者を解雇することができない。",a:true,e:"労契法17条1項。期間途中の解雇は、16条の解雇権濫用法理よりも厳格に「やむを得ない事由」が必要と解される。",topic:"労働契約法"},
 {id:"X8-007",s:8,q:"有期労働契約について、必要以上に短い期間を定めて反復更新することは労働契約法で禁止されており、違反した使用者には罰則が科される。",a:false,e:"労契法17条2項は「配慮しなければならない」とする配慮義務。労働契約法には罰則規定が置かれていない。",topic:"労働契約法"},
 {id:"X8-008",s:8,q:"無期転換申込権の行使により成立する期間の定めのない労働契約の労働条件は、別段の定めがある部分を除き、直前の有期労働契約と同一(契約期間を除く)となる。",a:true,e:"労契法18条1項後段。別段の定め(労働協約・就業規則・個別合意)がなければ、期間以外は従前と同じ労働条件となる。",topic:"労働契約法"},
 {id:"X8-009",s:8,q:"無期転換の通算契約期間の計算において、有期労働契約と次の有期労働契約との間に契約のない期間が3か月以上あれば、それ以前の契約期間は通算されない。",a:false,e:"労契法18条2項。空白期間(クーリング期間)は原則6か月以上。前の通算期間が1年未満ならその2分の1以上。",topic:"労働契約法"},
 {id:"X8-010",s:8,q:"有期特措法に基づく計画の認定を受けた事業主の下では、定年後引き続き雇用される有期雇用労働者について、定年後の継続雇用期間中は無期転換申込権が発生しない。",a:true,e:"専門的知識等を有する有期雇用労働者等に関する特別措置法。第二種計画認定を受けた場合の特例。",topic:"労働契約法"},
 {id:"X8-011",s:8,q:"有期特措法の特例により、高度専門職(年収要件あり)が一定期間内に完了するプロジェクトに従事する場合は、その期間の長さにかかわらず無期転換申込権は発生しない。",a:false,e:"特例の対象はプロジェクトの完了までの期間で、上限は10年。10年を超えれば無期転換申込権が発生する。",topic:"労働契約法"},
 {id:"X8-012",s:8,q:"雇止め法理(労働契約法19条)が適用されるためには、労働者が契約期間満了日までに更新の申込みをしたか、又は期間満了後遅滞なく有期労働契約の締結の申込みをしたことが必要である。",a:true,e:"労契法19条。申込みは要式を問わず、雇止めに対して反対の意思表示が伝われば足りると解されている。",topic:"労働契約法"},
 {id:"X8-013",s:8,q:"雇止め法理により雇止めが認められない場合、使用者は従前と同一の労働条件で申込みを承諾したものとみなされ、その契約は期間の定めのないものとなる。",a:false,e:"労契法19条では契約期間を含め従前と同一の労働条件で承諾したとみなされ、有期のまま更新される。無期化は18条の効果。",topic:"労働契約法"},
 {id:"X8-014",s:8,q:"就業規則の変更による労働条件の変更の合理性は、労働者の受ける不利益の程度、変更の必要性、変更後の内容の相当性、労働組合等との交渉の状況その他の事情に照らして判断される。",a:true,e:"労契法10条。変更後の就業規則の周知と合理性が要件。考慮要素が条文に列挙されている。",topic:"労働契約法"},
 {id:"X8-015",s:8,q:"就業規則の変更によっては変更されない労働条件として合意していた部分についても、合理的な就業規則の変更であれば、変更後の就業規則の内容が及ぶ。",a:false,e:"労契法10条ただし書。そのような合意部分には、12条に該当する場合を除き、就業規則の変更は及ばない。",topic:"労働契約法"},
 {id:"X8-016",s:8,q:"労働契約法3条は、仕事と生活の調和への配慮について定めているが、就業の実態に応じた均衡の考慮については定めていない。",a:false,e:"労契法3条2項に均衡考慮の原則、3項に仕事と生活の調和への配慮が定められている。",topic:"労働契約法"},
 {id:"X8-017",s:8,q:"労働組合法上の労働者とは、職業の種類を問わず、賃金、給料その他これに準ずる収入によって生活する者をいい、失業者も含まれ得る。",a:true,e:"労組法3条。現に使用されていることを要件とせず、労基法上の労働者より広い概念。",topic:"労働組合法"},
 {id:"X8-018",s:8,q:"主として政治運動又は社会運動を目的とする団体であっても、労働者が主体となって自主的に組織されていれば、労働組合法上の労働組合に該当する。",a:false,e:"労組法2条3号・4号。共済事業その他福利事業のみを目的とするもの(3号)、主として政治運動又は社会運動を目的とするもの(4号)は労働組合に当たらない。",topic:"労働組合法"},
 {id:"X8-019",s:8,q:"使用者が、労働者が労働時間中に時間又は賃金を失うことなく使用者と協議し又は交渉することを許すことは、経費援助の不当労働行為に当たらない。",a:true,e:"労組法7条3号ただし書。厚生資金・福利基金への寄附、最小限の広さの事務所の供与も除外される。",topic:"労働組合法"},
 {id:"X8-020",s:8,q:"不当労働行為の救済の申立ては、行為の日(継続する行為はその終了した日)から6か月以内にしなければならない。",a:false,e:"労組法27条2項。1年を経過した事件に係るものは、労働委員会は受けることができない。",topic:"労働組合法"},
 {id:"X8-021",s:8,q:"労働者が労働委員会に不当労働行為の申立てをしたことを理由として、使用者がその労働者を解雇することは、不当労働行為となる。",a:true,e:"労組法7条4号。申立て、再審査の申立て、証拠の提示・発言を理由とする不利益取扱いを禁止。",topic:"労働組合法"},
 {id:"X8-022",s:8,q:"労働協約に3年を超える有効期間の定めをした場合、その労働協約は全体として無効となる。",a:false,e:"労組法15条2項。3年を超える定めをした労働協約は、3年の有効期間の定めをしたものとみなされる。",topic:"労働組合法"},
 {id:"X8-023",s:8,q:"有効期間の定めがない労働協約は、当事者の一方が、署名し又は記名押印した文書によって、解約しようとする日の少なくとも90日前に相手方に予告して解約することができる。",a:true,e:"労組法15条3項・4項。",topic:"労働組合法"},
 {id:"X8-024",s:8,q:"労働協約に定める労働条件その他の労働者の待遇に関する基準に違反する労働契約の部分は無効となり、無効となった部分は基準の定めるところによる。",a:true,e:"労組法16条(規範的効力)。労働契約に定めがない部分も基準の定めるところによる。",topic:"労働組合法"},
 {id:"X8-025",s:8,q:"一の地域において従業する同種の労働者の大部分が一の労働協約の適用を受けるに至ったときは、何らの手続を要せず、当該地域の他の同種の労働者にも当該協約が適用される。",a:false,e:"労組法18条(地域的一般的拘束力)。当事者の申立て、労働委員会の決議、厚労大臣又は都道府県知事の決定が必要。",topic:"労働組合法"},
 {id:"X8-026",s:8,q:"労働組合は、労働委員会の資格審査を経て労働組合法に適合する旨の証明を受け、主たる事務所の所在地で登記することによって法人となる。",a:true,e:"労組法11条1項。法人格の取得にも5条の資格審査が必要。",topic:"労働組合法"},
 {id:"X8-027",s:8,q:"労働組合の規約には、同盟罷業は組合員又は代議員の直接無記名投票の3分の2以上の賛成で決定しなければ開始しないことを定めなければならない。",a:false,e:"労組法5条2項8号。直接無記名投票の「過半数」による決定。",topic:"労働組合法"},
 {id:"X8-028",s:8,q:"中央労働委員会は使用者委員、労働者委員及び公益委員各15人で組織され、公益委員は両議院の同意を得て内閣総理大臣が任命する。",a:true,e:"労組法19条の3。使用者委員は使用者団体の推薦、労働者委員は労働組合の推薦に基づき任命される。",topic:"労働組合法"},
 {id:"X8-029",s:8,q:"使用者が都道府県労働委員会の救済命令について中央労働委員会に再審査の申立てをしないときは、命令の交付の日から30日以内に取消しの訴えを提起することができる。",a:true,e:"労組法27条の19第1項。再審査の申立ては原則として命令交付の日から15日以内。",topic:"労働組合法"},
 {id:"X8-030",s:8,q:"労働組合の団体交渉その他の行為であれば、暴力の行使を伴うものであっても刑事免責の対象となる。",a:false,e:"労組法1条2項ただし書。いかなる場合においても、暴力の行使は正当な行為と解釈されてはならない。",topic:"労働組合法"},
 {id:"X8-031",s:8,q:"労働関係調整法において労働争議とは、労働関係の当事者間で労働関係に関する主張が一致しないで、争議行為が発生している状態又は発生するおそれがある状態をいう。",a:true,e:"労調法6条。争議行為(7条)は同盟罷業、怠業、作業所閉鎖等で業務の正常な運営を阻害するもの。",topic:"労働関係調整法"},
 {id:"X8-032",s:8,q:"公益事業に関する事件について争議行為をするには、その争議行為をしようとする日の少なくとも30日前までに、労働委員会及び厚生労働大臣又は都道府県知事に通知しなければならない。",a:false,e:"労調法37条1項。少なくとも10日前までに通知する。",topic:"労働関係調整法"},
 {id:"X8-033",s:8,q:"緊急調整の決定は内閣総理大臣が行い、その公表があったときは、関係当事者は公表の日から50日間は争議行為をすることができない。",a:true,e:"労調法35条の2・38条。決定に当たっては、あらかじめ中央労働委員会の意見を聴かなければならない。",topic:"労働関係調整法"},
 {id:"X8-034",s:8,q:"労働委員会による斡旋は、関係当事者の双方からの申請がなければ開始することができない。",a:false,e:"労調法12条。当事者の一方の申請又は職権に基づいても、労働委員会の会長は斡旋員に斡旋させることができる。",topic:"労働関係調整法"},
 {id:"X8-035",s:8,q:"工場事業場における安全保持の施設の正常な維持又は運行を停廃し、又はこれを妨げる行為は、争議行為としてでもこれをなすことはできない。",a:true,e:"労調法36条。",topic:"労働関係調整法"},
 {id:"X8-036",s:8,q:"内閣総理大臣は、国会の承認を経て、業務の停廃が国民経済を著しく阻害し又は公衆の日常生活を著しく危うくする事業を、1年以内の期間を限り公益事業として指定することができる。",a:true,e:"労調法8条2項。本来の公益事業は運輸、郵便・信書便・電気通信、水道・電気・ガス、医療・公衆衛生。",topic:"労働関係調整法"},
 {id:"X8-037",s:8,q:"最低賃金額は時間、日、週又は月によって定めることとされており、地域別最低賃金は日額で定められている。",a:false,e:"最賃法3条。最低賃金額は時間によって定める(時間額のみ)。",topic:"最低賃金法"},
 {id:"X8-038",s:8,q:"地域別最低賃金は、地域における労働者の生計費及び賃金並びに通常の事業の賃金支払能力を考慮して定められ、生計費の考慮に当たっては生活保護に係る施策との整合性に配慮する。",a:true,e:"最賃法9条2項・3項。",topic:"最低賃金法"},
 {id:"X8-039",s:8,q:"派遣中の労働者については、派遣先の事業場の所在地を含む地域について決定された地域別最低賃金が適用される。",a:true,e:"最賃法13条。派遣元ではなく派遣先の地域(特定最賃は派遣先の産業)の最低賃金による。",topic:"最低賃金法"},
 {id:"X8-040",s:8,q:"最低賃金の概要を労働者に周知させる措置は、使用者の努力義務にとどまる。",a:false,e:"最賃法8条。常時作業場の見やすい場所に掲示する等の方法により周知させるための措置をとらなければならない(義務)。",topic:"最低賃金法"},
 {id:"X8-041",s:8,q:"地域別最低賃金額以上の賃金を支払わなかった使用者は、50万円以下の罰金に処せられる。",a:true,e:"最賃法40条。特定最低賃金(船員に適用されるものを除く)の不払いは労基法24条違反として扱われる。",topic:"最低賃金法"},
 {id:"X8-042",s:8,q:"特定最低賃金は厚生労働大臣又は都道府県労働局長が職権でのみ決定するものであり、関係労使の申出によって決定されることはない。",a:false,e:"最賃法15条。労働者又は使用者の全部又は一部を代表する者の申出を受け、最低賃金審議会の調査審議を経て決定する。",topic:"最低賃金法"},
 {id:"X8-043",s:8,q:"最低賃金の減額の特例の対象には、認定職業訓練を受ける者のうち一定の者、軽易な業務に従事する者、断続的労働に従事する者が含まれる。",a:true,e:"最賃法7条。障害により労働能力の著しく低い者、試の使用期間中の者と合わせ5類型。いずれも労働局長の許可が必要。",topic:"最低賃金法"},
 {id:"X8-044",s:8,q:"地域別最低賃金を決定するかどうかは、各都道府県労働局長が地域の実情に応じて任意に判断することができる。",a:false,e:"最賃法9条1項。地域別最低賃金は、あまねく全国各地域について決定されなければならない(必要的決定)。",topic:"最低賃金法"},
 {id:"X8-045",s:8,q:"中央最低賃金審議会及び地方最低賃金審議会は、いずれも厚生労働省に置かれる。",a:false,e:"最賃法20条。中央最低賃金審議会は厚生労働省に、地方最低賃金審議会は都道府県労働局に置かれる。",topic:"最低賃金法"},
 {id:"X8-046",s:8,q:"事業主は、退職した労働者の賃金(退職手当を除く)を退職日までに支払わなかった場合、退職日の翌日から支払をする日まで年14.6%の率による遅延利息を支払わなければならない。",a:true,e:"賃確法6条1項。退職日後に支払期日が到来する賃金は、その支払期日の翌日から起算する。",topic:"賃金支払確保法"},
 {id:"X8-047",s:8,q:"事業主は、退職手当の支払に充てるべき額について保全措置を講ずることが、罰則付きで義務付けられている。",a:false,e:"賃確法5条。退職手当の保全措置は努力義務。貯蓄金(社内預金)の保全措置(3条)は義務。",topic:"賃金支払確保法"},
 {id:"X8-048",s:8,q:"未払賃金の立替払の対象となる事業主は、労災保険の適用事業の事業主で、1年以上事業活動を行っていたものである。",a:true,e:"賃確法7条・施行規則。破産等の法律上の倒産のほか、中小企業の事実上の倒産も対象。",topic:"賃金支払確保法"},
 {id:"X8-049",s:8,q:"未払賃金の立替払の額は未払賃金総額の全額(年齢による上限あり)であり、未払の賞与も対象となる。",a:false,e:"立替払は未払賃金総額の100分の80(年齢別上限あり)。対象は定期賃金と退職手当で、賞与は含まれない。",topic:"賃金支払確保法"},
 {id:"X8-050",s:8,q:"未払賃金の立替払の対象となるのは、破産手続開始等の申立て(事実上の倒産は認定申請)の日の6か月前の日から2年の間に退職した者である。",a:true,e:"賃確法7条・施行令3条。",topic:"賃金支払確保法"},
 {id:"X8-051",s:8,q:"未払賃金の立替払事業は、都道府県労働局が立替払金を直接支払う方法で実施されている。",a:false,e:"立替払事業は独立行政法人労働者健康安全機構が実施する。事実上の倒産の認定は労働基準監督署長が行う。",topic:"賃金支払確保法"},
 {id:"X8-052",s:8,q:"職場のパワーハラスメントとは、職場において行われる優越的な関係を背景とした言動であって、業務上必要かつ相当な範囲を超えたものにより、労働者の就業環境が害されるものをいう。",a:true,e:"労働施策総合推進法30条の2第1項。3つの要素すべてを満たすものが該当する。",topic:"労働施策総合推進法"},
 {id:"X8-053",s:8,q:"事業主は、労働者がパワーハラスメントの相談を行ったことを理由として不利益な取扱いをしないよう努めなければならないとされ、努力義務にとどまる。",a:false,e:"同法30条の2第2項。相談したこと、事実を述べたことを理由とする解雇その他不利益取扱いは禁止される。",topic:"労働施策総合推進法"},
 {id:"X8-054",s:8,q:"事業主は、労働者の募集及び採用について、厚生労働省令で定めるときを除き、その年齢にかかわりなく均等な機会を与えなければならない。",a:true,e:"同法9条。例外は定年年齢を上限とする募集、長期勤続によるキャリア形成を図る若年者の募集等。",topic:"労働施策総合推進法"},
 {id:"X8-055",s:8,q:"事業主は、外国人を雇い入れた場合、特別永住者を含むすべての外国人について、その氏名、在留資格等を厚生労働大臣に届け出なければならない。",a:false,e:"同法28条。特別永住者は届出の対象外。在留資格「外交」「公用」の者も除かれる。",topic:"労働施策総合推進法"},
 {id:"X8-056",s:8,q:"1の事業所において1か月以内に30人以上の労働者が経済的事情等により離職する場合、事業主は大量雇用変動の届出をしなければならない。",a:true,e:"同法27条。届出先は公共職業安定所長で、原則として最後の離職の1か月前までに行う。",topic:"労働施策総合推進法"},
 {id:"X8-057",s:8,q:"パワーハラスメントに関する紛争は、都道府県労働局長の助言・指導・勧告の対象となるが、紛争調整委員会による調停の対象とはならない。",a:false,e:"同法30条の5・30条の6。紛争調整委員会による調停の対象となる。",topic:"労働施策総合推進法"},
 {id:"X8-058",s:8,q:"雇用保険の被保険者となる外国人に係る外国人雇用状況の届出は、雇用保険被保険者資格取得届等を提出することにより行ったものとされる。",a:true,e:"同法28条・施行規則。被保険者でない外国人は、雇入れ・離職の翌月末日までに届出書を提出する。",topic:"労働施策総合推進法"},
 {id:"X8-059",s:8,q:"学校は、厚生労働大臣に届け出て、無料の職業紹介事業を行うことができる。",a:true,e:"職安法33条の2。学校・専修学校等は届出制。一般の無料職業紹介事業は許可制(33条)。",topic:"職業安定法"},
 {id:"X8-060",s:8,q:"有料職業紹介事業の許可の有効期間は、新規・更新とも3年である。",a:false,e:"職安法32条の6。新規は3年、更新後は5年。",topic:"職業安定法"},
 {id:"X8-061",s:8,q:"有料職業紹介事業者は、原則として求職者から手数料を徴収してはならないが、芸能家、モデル、一定の年収を超える経営管理者・科学技術者・熟練技能者は例外とされている。",a:true,e:"職安法32条の3・施行規則。年収要件は700万円超。",topic:"職業安定法"},
 {id:"X8-062",s:8,q:"労働組合は、厚生労働大臣の許可を受ければ、有料で労働者供給事業を行うことができる。",a:false,e:"職安法45条。労働組合等が許可を受けて行えるのは無料の労働者供給事業のみ。",topic:"職業安定法"},
 {id:"X8-063",s:8,q:"労働者を雇用しようとする者が、その被用者以外の者に報酬を与えて労働者の募集に従事させようとするときは、厚生労働大臣の許可を受けなければならない。",a:true,e:"職安法36条1項。報酬を与えない委託募集は届出で足りる(同条3項)。",topic:"職業安定法"},
 {id:"X8-064",s:8,q:"公共職業安定所は、求人の申込みはすべて受理しなければならず、労働関係法令違反を理由として求人を受理しないことは認められていない。",a:false,e:"職安法5条の6。内容が法令に違反する求人や、一定の労働関係法令違反で処分・公表された者からの求人等は受理しないことができる。",topic:"職業安定法"},
 {id:"X8-065",s:8,q:"職業紹介事業者、求人者、募集を行う者等は、求職者等の個人情報を収集、保管又は使用するに当たっては、業務の目的の達成に必要な範囲内で行わなければならない。",a:true,e:"職安法5条の5。本人の同意その他正当な事由がある場合は除かれる。",topic:"職業安定法"},
 {id:"X8-066",s:8,q:"公共職業安定所及び職業紹介事業者は、職業紹介に当たり、求職者に対し、その者が従事すべき業務の内容、賃金、労働時間その他の労働条件を明示しなければならない。",a:true,e:"職安法5条の3第1項。求人者も求人の申込みに当たり公共職業安定所等に労働条件を明示する(同条2項)。",topic:"職業安定法"},
 {id:"X8-067",s:8,q:"募集情報等提供事業者は、提供する募集情報等について虚偽の表示をしないようにする義務を負わず、その責任は募集主のみが負う。",a:false,e:"職安法5条の4。募集情報等提供事業者も虚偽・誤解を生じさせる表示の禁止や正確・最新の内容に保つ措置の対象(2022年10月施行)。",topic:"職業安定法"},
 {id:"X8-068",s:8,q:"労働者になろうとする者に関する情報を収集して行う募集情報等提供事業(特定募集情報等提供事業)を行おうとする者は、厚生労働大臣に届け出なければならない。",a:true,e:"職安法43条の2。2022年10月施行の改正で届出制が設けられた。",topic:"職業安定法"},
 {id:"X8-069",s:8,q:"港湾運送業務、建設業務及び警備業務については、労働者派遣事業を行ってはならない。",a:true,e:"派遣法4条1項。医療関係業務も政令で原則禁止(紹介予定派遣、産休等代替、へき地等は例外)。",topic:"労働者派遣法"},
 {id:"X8-070",s:8,q:"労働者派遣事業の許可の有効期間は、新規・更新とも5年である。",a:false,e:"派遣法10条。新規は3年、更新後は5年。2015年改正で許可制に一本化された。",topic:"労働者派遣法"},
 {id:"X8-071",s:8,q:"派遣元事業主は、派遣先を離職した後1年を経過しない者を当該派遣先に派遣してはならないが、60歳以上の定年退職者は除かれる。",a:true,e:"派遣法40条の9・35条の5。派遣先は該当者を受け入れる場合、派遣元に通知しなければならない。",topic:"労働者派遣法"},
 {id:"X8-072",s:8,q:"派遣元事業主に無期雇用されている派遣労働者についても、派遣先の同一の組織単位で3年を超えて派遣就業させることはできない。",a:false,e:"派遣法40条の2・40条の3。無期雇用派遣労働者、60歳以上の者等は期間制限の対象外。",topic:"労働者派遣法"},
 {id:"X8-073",s:8,q:"派遣先が事業所単位の派遣可能期間を延長しようとするときは、抵触日の1か月前の日までに、過半数労働組合等の意見を聴かなければならない。",a:true,e:"派遣法40条の2第4項。異議が述べられたときは延長の理由等を説明しなければならない。",topic:"労働者派遣法"},
 {id:"X8-074",s:8,q:"派遣先が期間制限に違反して派遣労働者を受け入れた場合であっても、派遣先が当該派遣労働者に労働契約の申込みをしたものとみなされることはない。",a:false,e:"派遣法40条の6。違法派遣を受け入れた時点で、派遣先が同一の労働条件で労働契約の申込みをしたものとみなされる(善意無過失を除く)。",topic:"労働者派遣法"},
 {id:"X8-075",s:8,q:"紹介予定派遣では、派遣就業開始前の面接や履歴書の送付など、派遣労働者を特定することを目的とする行為が認められる。",a:true,e:"派遣法26条6項。通常の派遣では派遣先は特定目的行為をしないよう努めるが、紹介予定派遣は例外。",topic:"労働者派遣法"},
 {id:"X8-076",s:8,q:"紹介予定派遣において、同一の派遣労働者について派遣就業できる期間は1年を超えてはならない。",a:false,e:"派遣元事業主が講ずべき措置に関する指針により、6か月を超えてはならない。",topic:"労働者派遣法"},
 {id:"X8-077",s:8,q:"派遣元事業主は、一定の要件を満たす労使協定を締結した場合には、派遣先均等・均衡方式によらず、労使協定方式により派遣労働者の待遇を決定することができる。",a:true,e:"派遣法30条の4。協定対象派遣労働者の賃金は、同種の業務に従事する一般労働者の平均的な賃金額以上とする。",topic:"労働者派遣法"},
 {id:"X8-078",s:8,q:"派遣先は、自社の労働者が利用する給食施設、休憩室及び更衣室について、派遣労働者に利用の機会を与えるよう配慮すれば足りる。",a:false,e:"派遣法40条3項。2020年4月から、利用の機会を与えなければならない(義務)。",topic:"労働者派遣法"},
 {id:"X8-079",s:8,q:"派遣元事業主が関係派遣先に労働者派遣をするときは、関係派遣先への派遣割合を100分の80以下としなければならない。",a:true,e:"派遣法23条の2。60歳以上の定年退職者は割合の計算から除かれる。",topic:"労働者派遣法"},
 {id:"X8-080",s:8,q:"派遣元管理台帳及び派遣先管理台帳は、いずれも労働者派遣の終了の日から1年間保存しなければならない。",a:false,e:"派遣法37条2項・42条2項。いずれも3年間保存。",topic:"労働者派遣法"},
 {id:"X8-081",s:8,q:"派遣元事業主は、同一の組織単位の業務に継続して3年間派遣就業する見込みがある特定有期雇用派遣労働者について、派遣先への直接雇用の依頼等の雇用安定措置を講じなければならない。",a:true,e:"派遣法30条。1年以上3年未満の見込みの者については努力義務。",topic:"労働者派遣法"},
 {id:"X8-082",s:8,q:"派遣元事業主は、労働者を派遣労働者として雇い入れようとするときは、その者に対し、待遇に関する事項等を明示し、講ずる措置の内容を説明しなければならない。",a:true,e:"派遣法31条の2。雇入れ時のほか、派遣時にも明示・説明が必要。",topic:"労働者派遣法"},
 {id:"X8-083",s:8,q:"事業主が定年の定めをする場合、当該定年は60歳を下回ることができないが、高年齢者が従事することが困難として厚生労働省令で定める坑内作業の業務に従事する労働者は除かれる。",a:true,e:"高年法8条・施行規則4条の2。",topic:"高年齢者雇用安定法"},
 {id:"X8-084",s:8,q:"65歳未満の定年を定めている事業主が講ずべき高年齢者雇用確保措置は、定年の引上げ及び継続雇用制度の導入の2つに限られる。",a:false,e:"高年法9条1項。定年の定めの廃止を含む3つのいずれかを講じなければならない。",topic:"高年齢者雇用安定法"},
 {id:"X8-085",s:8,q:"継続雇用制度には、事業主が特殊関係事業主(子会社・関連会社等)と契約を締結し、当該特殊関係事業主が定年後の高年齢者を引き続いて雇用する制度も含まれる。",a:true,e:"高年法9条2項。グループ内の他社での継続雇用も認められる。",topic:"高年齢者雇用安定法"},
 {id:"X8-086",s:8,q:"継続雇用制度の対象者を労使協定の基準により限定できる経過措置は、2026年4月時点でも適用されている。",a:false,e:"平成24年改正法附則の経過措置は2025年3月31日で終了した。2025年4月以降は希望者全員が対象(2026年4月時点)。",topic:"高年齢者雇用安定法"},
 {id:"X8-087",s:8,q:"70歳までの就業確保措置として創業支援等措置を講ずる場合には、計画を作成し、過半数労働組合等の同意を得なければならない。",a:true,e:"高年法10条の2第1項ただし書。雇用によらない措置(業務委託・社会貢献事業)のため同意が要件となっている。",topic:"高年齢者雇用安定法"},
 {id:"X8-088",s:8,q:"解雇等により離職する45歳以上70歳未満の高年齢者等が希望するときに求職活動支援書を作成・交付することは、事業主の努力義務にとどまる。",a:false,e:"高年法17条1項。希望するときは求職活動支援書を作成し、交付しなければならない(義務)。",topic:"高年齢者雇用安定法"},
 {id:"X8-089",s:8,q:"事業主は、1か月以内に5人以上の高年齢者等が解雇等により離職する場合には、あらかじめ公共職業安定所長に多数離職の届出をしなければならない。",a:true,e:"高年法16条。対象は45歳以上70歳未満の者。",topic:"高年齢者雇用安定法"},
 {id:"X8-090",s:8,q:"事業主は、毎年1回、4月1日現在の定年及び継続雇用制度等の状況を厚生労働大臣に報告しなければならない。",a:false,e:"高年法52条・施行規則。報告の基準日は毎年6月1日。",topic:"高年齢者雇用安定法"},
 {id:"X8-091",s:8,q:"事業主は、労働者の募集・採用に当たり、やむを得ない理由により一定の年齢(65歳以下のものに限る)を下回ることを条件とするときは、求職者にその理由を示さなければならない。",a:true,e:"高年法20条1項。",topic:"高年齢者雇用安定法"},
 {id:"X8-092",s:8,q:"事業主は、障害者である労働者について、過重な負担を及ぼすこととなる場合を除き、障害の特性に配慮した必要な措置(合理的配慮)を講じなければならない。",a:true,e:"障害者雇用促進法36条の3。募集・採用時は障害者からの申出により講ずる(36条の2)。",topic:"障害者雇用促進法"},
 {id:"X8-093",s:8,q:"障害者雇用促進法の差別禁止・合理的配慮の対象となる障害者は、障害者手帳の所持者に限られる。",a:false,e:"同法2条1号。心身の機能の障害により長期にわたり職業生活に相当の制限を受ける者で、手帳の有無を問わない。",topic:"障害者雇用促進法"},
 {id:"X8-094",s:8,q:"民間企業の障害者の法定雇用率は2.5%であり、常用労働者40.0人以上の事業主が障害者を1人以上雇用する義務を負う(2026年4月時点)。",a:true,e:"2024年4月から2.5%。2026年7月から2.7%(対象37.5人以上)に引き上げられる。",topic:"障害者雇用促進法"},
 {id:"X8-095",s:8,q:"週所定労働時間が10時間以上20時間未満の障害者は、障害の種類を問わず、実雇用率の算定上0.5人として算定される。",a:false,e:"2024年4月から0.5人と算定されるのは、重度身体障害者・重度知的障害者・精神障害者に限られる。",topic:"障害者雇用促進法"},
 {id:"X8-096",s:8,q:"障害者を5人以上雇用する事業所の事業主は、障害者職業生活相談員を選任し、職業生活に関する相談・指導を行わせなければならない。",a:true,e:"同法79条・施行規則。資格認定講習の修了者等から選任する。",topic:"障害者雇用促進法"},
 {id:"X8-097",s:8,q:"事業主は、障害者である労働者を解雇する場合であっても、公共職業安定所長への届出は必要とされていない。",a:false,e:"同法81条。障害者の解雇(労働者の責に帰すべき理由による場合等を除く)は、速やかに公共職業安定所長に届け出なければならない。",topic:"障害者雇用促進法"},
 {id:"X8-098",s:8,q:"障害者の雇用の促進等に関する取組が優良な中小事業主(常時雇用する労働者300人以下)を厚生労働大臣が認定する制度を「もにす認定」という。",a:true,e:"同法77条。",topic:"障害者雇用促進法"},
 {id:"X8-099",s:8,q:"特例子会社に雇用される障害者は、親会社の実雇用率の算定に含めることができない。",a:false,e:"同法44条。要件を満たし厚生労働大臣の認定を受けた特例子会社の労働者は、親会社に雇用されるものとみなして算定できる。",topic:"障害者雇用促進法"},
 {id:"X8-100",s:8,q:"事業主は、障害者である労働者からの相談に応じ、適切に対応するために必要な体制の整備その他の雇用管理上必要な措置を講じなければならない。",a:true,e:"同法36条の4。合理的配慮に関する相談体制の整備義務。",topic:"障害者雇用促進法"},
 {id:"X8-101",s:8,q:"事業主は、労働者の職種及び雇用形態の変更について、労働者の性別を理由として差別的取扱いをしてはならない。",a:true,e:"均等法6条3号。退職の勧奨、定年、解雇、労働契約の更新も同条4号で規制される。",topic:"男女雇用機会均等法"},
 {id:"X8-102",s:8,q:"間接差別となる措置のうち、転居を伴う転勤に応じることができることを要件とするものは、総合職の募集・採用に限って規制される。",a:false,e:"均等法施行規則2条2号。2014年7月から、すべての労働者の募集・採用、昇進、職種の変更が対象。",topic:"男女雇用機会均等法"},
 {id:"X8-103",s:8,q:"事業主は、女性労働者が婚姻し、妊娠し、又は出産したことを退職理由として予定する定めをしてはならない。",a:true,e:"均等法9条1項。婚姻を理由とする解雇も同条2項で禁止される。",topic:"男女雇用機会均等法"},
 {id:"X8-104",s:8,q:"女性労働者が母子保健法による保健指導又は健康診査を受けるために必要な時間を確保することは、事業主の努力義務にとどまる。",a:false,e:"均等法12条。必要な時間を確保できるようにしなければならない(義務)。指導事項を守るための措置(13条)も義務。",topic:"男女雇用機会均等法"},
 {id:"X8-105",s:8,q:"職場におけるセクシュアルハラスメントには同性に対するものも含まれ、被害者の性的指向・性自認にかかわらず措置の対象となる。",a:true,e:"均等法11条・セクハラ指針。",topic:"男女雇用機会均等法"},
 {id:"X8-106",s:8,q:"事業主は、他の事業主から、その講ずるセクシュアルハラスメント防止措置の実施に関し必要な協力を求められた場合、これに応ずる法的義務を負う。",a:false,e:"均等法11条3項。協力に応ずるように努めなければならない(努力義務)。",topic:"男女雇用機会均等法"},
 {id:"X8-107",s:8,q:"均等法に定める事項に関する紛争(募集・採用に関するものを除く)について当事者の申請があった場合、都道府県労働局長は紛争調整委員会に調停を行わせることができる。",a:true,e:"均等法18条。募集・採用に関する紛争は調停の対象外だが、労働局長の助言・指導・勧告の対象にはなる。",topic:"男女雇用機会均等法"},
 {id:"X8-108",s:8,q:"厚生労働大臣は、均等法に違反している事業主に勧告をし、事業主がこれに従わなかった場合でも、その旨を公表することはできない。",a:false,e:"均等法30条。勧告に従わなかったときは、その旨を公表することができる。",topic:"男女雇用機会均等法"},
 {id:"X8-109",s:8,q:"事業主は、職場における妊娠・出産等に関する言動により女性労働者の就業環境が害されることのないよう、相談体制の整備等の雇用管理上必要な措置を講じなければならない。",a:true,e:"均等法11条の3。育児休業等に関するハラスメントは育介法25条で規定。",topic:"男女雇用機会均等法"},
 {id:"X8-110",s:8,q:"育児休業(産後パパ育休を除く)は、子1人につき原則として2回まで分割して取得することができる。",a:true,e:"育介法5条2項。2022年10月施行。産後パパ育休も別に2回まで分割できる。",topic:"育児・介護休業法"},
 {id:"X8-111",s:8,q:"産後パパ育休(出生時育児休業)は、原則として休業開始予定日の1か月前までに申し出なければならない。",a:false,e:"育介法9条の3第3項。原則2週間前まで(雇用環境整備等を定めた労使協定がある場合は1か月前までとすることも可)。",topic:"育児・介護休業法"},
 {id:"X8-112",s:8,q:"産後パパ育休中は、労使協定を締結している場合に限り、労働者が合意した範囲内で休業中に就業させることができる。",a:true,e:"育介法9条の5。就業可能日数等には上限がある。",topic:"育児・介護休業法"},
 {id:"X8-113",s:8,q:"有期雇用労働者が育児休業を申し出るには、同一の事業主に引き続き1年以上雇用されていることが法律上の要件とされている(2026年4月時点)。",a:false,e:"2022年4月にこの要件は廃止された。子が1歳6か月に達する日までに契約満了が明らかでないことが要件(労使協定による除外は可)。",topic:"育児・介護休業法"},
 {id:"X8-114",s:8,q:"パパ・ママ育休プラスにより父母がともに育児休業を取得する場合、子が1歳2か月に達するまでの間に、1人当たり1年(産後休業期間等を含む)を上限として育児休業を取得できる。",a:true,e:"育介法9条の6。",topic:"育児・介護休業法"},
 {id:"X8-115",s:8,q:"介護休業の対象家族のうち、祖父母、兄弟姉妹及び孫については、労働者と同居し、かつ扶養していることが要件とされている。",a:false,e:"2017年1月に同居・扶養の要件は廃止。配偶者、父母、子、配偶者の父母、祖父母、兄弟姉妹、孫が対象家族。",topic:"育児・介護休業法"},
 {id:"X8-116",s:8,q:"介護休暇は、要介護状態にある対象家族が1人であれば1年度に5日、2人以上であれば10日を限度として、時間単位でも取得することができる。",a:true,e:"育介法16条の5・施行規則。2021年1月から時間単位での取得が可能。",topic:"育児・介護休業法"},
 {id:"X8-117",s:8,q:"所定外労働の制限(残業免除)を請求できるのは、3歳に満たない子を養育する労働者に限られる(2026年4月時点)。",a:false,e:"2025年4月から、小学校就学の始期に達するまでの子を養育する労働者に拡大された(育介法16条の8)。",topic:"育児・介護休業法"},
 {id:"X8-118",s:8,q:"事業主は、小学校就学の始期に達するまでの子を養育する労働者が請求したときは、事業の正常な運営を妨げる場合を除き、1か月24時間、1年150時間を超える時間外労働をさせてはならない。",a:true,e:"育介法17条。要介護状態の対象家族を介護する労働者も同様(18条)。",topic:"育児・介護休業法"},
 {id:"X8-119",s:8,q:"深夜業の制限の請求は、1回につき1か月以上1年以内の期間について行うことができる。",a:false,e:"育介法19条。深夜業の制限は1回につき1か月以上6か月以内。1か月以上1年以内は所定外労働・時間外労働の制限。",topic:"育児・介護休業法"},
 {id:"X8-120",s:8,q:"子の看護等休暇は、子の病気・けがの看護や予防接種・健康診断のほか、感染症に伴う学級閉鎖等や入園(入学)式・卒園式への参加のためにも取得できる(2026年4月時点)。",a:true,e:"2025年4月施行の改正で名称が変わり、取得事由が追加された(育介法16条の2)。",topic:"育児・介護休業法"},
 {id:"X8-121",s:8,q:"男性労働者の育児休業等の取得状況を年1回公表する義務を負うのは、常時雇用する労働者が1,000人を超える事業主に限られる(2026年4月時点)。",a:false,e:"2025年4月から、常時雇用する労働者が300人を超える事業主に拡大された(育介法22条の2)。",topic:"育児・介護休業法"},
 {id:"X8-122",s:8,q:"事業主は、3歳から小学校就学前の子を養育する労働者について、始業時刻等の変更、テレワーク等、保育施設の設置運営等、養育両立支援休暇、短時間勤務制度のうち2つ以上の措置を講じなければならない(2026年4月時点)。",a:true,e:"柔軟な働き方を実現するための措置(2025年10月施行)。労働者は講じられた措置から1つを選んで利用できる。",topic:"育児・介護休業法"},
 {id:"X8-123",s:8,q:"介護のための所定労働時間の短縮等の措置は、利用開始の日から1年以上の期間内に1回以上利用できるものであれば足りる。",a:false,e:"育介法23条3項・施行規則。利用開始から3年以上の期間内に2回以上利用できるものでなければならない。",topic:"育児・介護休業法"},
 {id:"X8-124",s:8,q:"事業主は、労働者を転勤させようとする場合に、就業場所の変更により子の養育又は家族の介護が困難となる労働者がいるときは、その状況に配慮しなければならない。",a:true,e:"育介法26条。",topic:"育児・介護休業法"},
 {id:"X8-125",s:8,q:"育児休業の申出は、1歳6か月まで及び2歳までの延長の場合も含め、すべて休業開始予定日の1か月前までに行わなければならない。",a:false,e:"育介法6条3項等。1歳までの休業は1か月前、1歳6か月・2歳までの延長は2週間前までに申し出る。",topic:"育児・介護休業法"},
 {id:"X8-126",s:8,q:"事業主は、労働者から本人又は配偶者の妊娠・出産等の申出があったときは、育児休業制度等を個別に周知し、取得の意向を確認するための措置を講じなければならない。",a:true,e:"育介法21条1項。取得を控えさせるような周知・意向確認は認められない。",topic:"育児・介護休業法"},
 {id:"X8-127",s:8,q:"短時間労働者とは、1週間の所定労働時間が、同一の事業主に雇用される通常の労働者の1週間の所定労働時間に比し短い労働者をいう。",a:true,e:"パート有期法2条1項。2020年改正で比較対象が事業所単位から事業主単位に改められた。",topic:"パートタイム・有期雇用労働法"},
 {id:"X8-128",s:8,q:"短時間・有期雇用労働者を雇い入れたときに昇給・退職手当・賞与の有無及び相談窓口を文書の交付等により明示することは努力義務であり、違反しても制裁はない。",a:false,e:"同法6条1項は義務で、違反すると10万円以下の過料(31条)。",topic:"パートタイム・有期雇用労働法"},
 {id:"X8-129",s:8,q:"職務の内容が通常の労働者と同一で、雇用関係が終了するまでの全期間において職務の内容及び配置の変更の範囲が通常の労働者と同一と見込まれる短時間・有期雇用労働者については、差別的取扱いが禁止される。",a:true,e:"同法9条(均等待遇)。",topic:"パートタイム・有期雇用労働法"},
 {id:"X8-130",s:8,q:"事業主は、短時間・有期雇用労働者から通常の労働者との待遇の相違の内容及び理由について説明を求められても、これを説明する義務はない。",a:false,e:"同法14条2項により説明義務がある。説明を求めたことを理由とする不利益取扱いも禁止(同条3項)。",topic:"パートタイム・有期雇用労働法"},
 {id:"X8-131",s:8,q:"事業主は、通常の労働者の募集内容の周知、通常の労働者への転換のための試験制度など、通常の労働者への転換を推進するための措置のいずれかを講じなければならない。",a:true,e:"同法13条。",topic:"パートタイム・有期雇用労働法"},
 {id:"X8-132",s:8,q:"常時10人以上の短時間・有期雇用労働者を雇用する事業所の事業主は、短時間・有期雇用管理者を選任しなければならず、違反には罰則がある。",a:false,e:"同法17条。短時間・有期雇用管理者の選任は努力義務。",topic:"パートタイム・有期雇用労働法"},
 {id:"X8-133",s:8,q:"不合理な待遇の禁止は、基本給、賞与その他の待遇のそれぞれについて、当該待遇の性質及び目的に照らして適切と認められる事情を考慮して判断される。",a:true,e:"同法8条。職務の内容、職務の内容・配置の変更の範囲、その他の事情を考慮し、個々の待遇ごとに判断する。",topic:"パートタイム・有期雇用労働法"},
 {id:"X8-134",s:8,q:"有期雇用労働者と無期雇用労働者との労働条件の相違は、2026年4月時点でも労働契約法20条により規律されている。",a:false,e:"労働契約法旧20条は2020年4月(中小企業は2021年4月)に削除され、パート有期法8条に統合された。",topic:"パートタイム・有期雇用労働法"},
 {id:"X8-135",s:8,q:"都道府県労働局長は、個別労働関係紛争に関し、当事者の双方又は一方から解決の援助を求められた場合には、必要な助言又は指導をすることができる。",a:true,e:"個別労働紛争解決促進法4条。援助を求めたことを理由とする不利益取扱いは禁止される。",topic:"個別労働紛争解決促進法"},
 {id:"X8-136",s:8,q:"紛争調整委員会によるあっせんの対象には、労働者の募集及び採用に関する事項についての紛争も含まれる。",a:false,e:"同法5条1項括弧書。募集・採用に関する紛争はあっせんの対象外(労働局長の助言・指導の対象にはなる)。",topic:"個別労働紛争解決促進法"},
 {id:"X8-137",s:8,q:"紛争調整委員会のあっせんは、委員のうちから会長が事件ごとに指名する3人のあっせん委員によって行われる。",a:true,e:"同法12条。",topic:"個別労働紛争解決促進法"},
 {id:"X8-138",s:8,q:"あっせんが打ち切られた場合、申請者が打切りの通知を受けた日から6か月以内に訴えを提起すれば、時効の完成猶予に関し、あっせん申請時に訴えの提起があったものとみなされる。",a:false,e:"同法16条。通知を受けた日から30日以内に訴えを提起した場合に限られる。",topic:"個別労働紛争解決促進法"},
 {id:"X8-139",s:8,q:"地方公共団体は、地域の実情に応じ、労働者、求職者又は事業主に対する情報の提供、相談、あっせんその他の必要な施策を推進するように努めるものとされる。",a:true,e:"同法20条1項。都道府県労働委員会による個別労働紛争のあっせん等はこれに基づく。",topic:"個別労働紛争解決促進法"},
 {id:"X8-140",s:8,q:"常時雇用する労働者の数が100人を超える一般事業主は、一般事業主行動計画を策定し、厚生労働大臣に届け出なければならない。",a:true,e:"次世代法12条。100人以下は努力義務。届出の窓口は都道府県労働局。",topic:"次世代育成支援対策推進法"},
 {id:"X8-141",s:8,q:"次世代育成支援対策推進法は、2025年3月31日限りでその効力を失った。",a:false,e:"2024年改正により有効期限が2035年3月31日まで10年間延長された(2026年4月時点)。",topic:"次世代育成支援対策推進法"},
 {id:"X8-142",s:8,q:"常時雇用100人超の事業主は、一般事業主行動計画の策定・変更に当たり、男性労働者の育児休業等の取得状況及び労働時間の状況を把握し、数値目標を定めなければならない(2026年4月時点)。",a:true,e:"2025年4月施行の改正で、状況把握と数値目標の設定が義務化された。",topic:"次世代育成支援対策推進法"},
 {id:"X8-143",s:8,q:"プラチナくるみん認定を受けた事業主は、一般事業主行動計画の策定・届出が免除されるが、次世代育成支援対策の実施状況を毎年公表しなければならない。",a:true,e:"次世代法15条の2〜15条の4。特例認定の効果。",topic:"次世代育成支援対策推進法"},
 {id:"X8-144",s:8,q:"常時雇用する労働者の数が100人を超える一般事業主は、女性の活躍に関する状況把握・課題分析を行ったうえで一般事業主行動計画を策定し、届け出なければならない。",a:true,e:"女性活躍推進法8条。2022年4月から101人以上に拡大。100人以下は努力義務。",topic:"女性活躍推進法"},
 {id:"X8-145",s:8,q:"プラチナえるぼし認定を受けた事業主であっても、一般事業主行動計画の策定・届出は免除されない。",a:false,e:"女性活躍推進法12条・13条。プラチナえるぼし認定を受けると策定・届出が免除される(毎年の情報公表が必要)。",topic:"女性活躍推進法"},
 {id:"X8-146",s:8,q:"事業主は、事業内職業能力開発計画を作成するように努めるとともに、職業能力開発推進者を選任するように努めなければならない。",a:true,e:"職業能力開発促進法11条・12条。いずれも努力義務。",topic:"職業能力開発促進法"},
 {id:"X8-147",s:8,q:"技能検定に合格した者は技能士と称することができるが、技能士でない者が技能士という名称を用いることは禁止されていない。",a:false,e:"能開法50条。技能士でない者は技能士という名称を用いてはならない(名称独占)。",topic:"職業能力開発促進法"},
 {id:"X8-148",s:8,q:"キャリアコンサルタントの登録は、5年ごとにその更新を受けなければ、その期間の経過によって効力を失う。",a:true,e:"能開法30条の20。名称独占資格で、守秘義務・信用失墜行為の禁止も定められている。",topic:"職業能力開発促進法"},
 {id:"X8-149",s:8,q:"事業主等が行う職業訓練のうち一定の基準に適合するものは、厚生労働大臣の認定を受けて認定職業訓練として実施することができる。",a:false,e:"能開法24条。認定職業訓練の認定は都道府県知事が行う。",topic:"職業能力開発促進法"},
 {id:"X8-150",s:8,q:"職業能力開発基本計画は、都道府県知事が策定する。",a:false,e:"能開法5条。厚生労働大臣が策定する。都道府県は別に都道府県職業能力開発計画を定める。",topic:"職業能力開発促進法"},
 {id:"X8-151",s:8,q:"事業主は、健康及び福祉を確保するために必要な終業から始業までの時間(勤務間インターバル)の設定に努めなければならない。",a:true,e:"労働時間等設定改善法2条1項。2019年4月施行の努力義務。",topic:"労働時間等設定改善法"},
 {id:"X8-152",s:8,q:"労働時間等設定改善法は、事業主が他の事業主との取引において著しく短い期限の設定等を行わないよう配慮することまでは求めていない。",a:false,e:"同法2条4項。取引上必要な配慮をするように努めなければならない。",topic:"労働時間等設定改善法"},
 {id:"X8-153",s:8,q:"事業主は、労働時間等の設定に当たり、育児・介護を行う労働者、単身赴任者、自ら職業能力の開発を図る者など特に配慮を必要とする労働者の事情を考慮する等の措置を講ずるように努めなければならない。",a:true,e:"同法2条2項。",topic:"労働時間等設定改善法"},
 {id:"X8-154",s:8,q:"中小企業退職金共済制度の共済契約者は、原則として従業員全員を被共済者として契約しなければならないが、期間を定めて雇用される者等は除くことができる。",a:true,e:"中小企業退職金共済法3条3項・施行規則。",topic:"中小企業退職金共済法"},
 {id:"X8-155",s:8,q:"中小企業退職金共済の掛金月額は、被共済者1人につき1,000円以上30,000円以下の範囲内で定める。",a:false,e:"中退法4条。通常は5,000円以上30,000円以下。短時間労働者は2,000円からの特例掛金月額がある。",topic:"中小企業退職金共済法"},
 {id:"X8-156",s:8,q:"中小企業退職金共済の退職金は、独立行政法人勤労者退職金共済機構から被共済者(又はその遺族)に直接支払われる。",a:true,e:"中退法。事業主を経由しないで支給される。",topic:"中小企業退職金共済法"},
 {id:"X8-157",s:8,q:"中小企業退職金共済において、掛金納付月数が1か月以上あれば、被共済者の退職時には必ず退職金が支給される。",a:false,e:"中退法10条。掛金納付月数が12か月未満の場合、退職金は支給されない。",topic:"中小企業退職金共済法"},
 {id:"X8-158",s:8,q:"特定受託事業者に係る取引の適正化等に関する法律(フリーランス・事業者間取引適正化等法)は、2024年11月1日に施行された。",a:true,e:"業務委託事業者の取引条件明示義務、特定業務委託事業者の報酬支払期日・就業環境整備の義務等を定める。",topic:"フリーランス法"},
 {id:"X8-159",s:8,q:"特定業務委託事業者は、特定受託事業者の給付を受領した日から起算して90日以内のできる限り短い期間内で報酬の支払期日を定めなければならない。",a:false,e:"同法4条1項。60日以内。再委託の場合は元委託の支払期日から30日以内とする特例がある。",topic:"フリーランス法"},
 {id:"X8-160",s:8,q:"特定業務委託事業者は、特定受託事業者に対するハラスメントについて、相談に応じ適切に対応するために必要な体制の整備その他の措置を講じなければならない。",a:true,e:"同法14条。セクハラ・マタハラ・パワハラが対象。",topic:"フリーランス法"},
 {id:"X8-161",s:8,q:"特定業務委託事業者が6か月以上の継続的業務委託を中途解除する場合、解除日の10日前までに予告すれば足りる。",a:false,e:"同法16条。原則として少なくとも30日前までに予告しなければならない。",topic:"フリーランス法"},
 {id:"X8-162",s:8,q:"新卒者等の募集を行う事業主は、応募者等から求めがあった場合、募集・採用、職業能力の開発・向上、雇用管理に関する状況の3類型について、それぞれ1つ以上の情報を提供しなければならない。",a:true,e:"若者雇用促進法13条等(青少年雇用情報の提供)。全項目の情報提供は努力義務(指針)。",topic:"若者雇用促進法"},
 {id:"X8-163",s:8,q:"労働組合法は1945年(昭和20年)に制定され、1949年(昭和24年)に全部改正された。",a:true,e:"労働関係調整法は1946年、労働基準法は1947年に制定された(労働三法)。",topic:"沿革"},
 {id:"X8-164",s:8,q:"生活保護法による保護を受けている世帯(保護を停止されている世帯を除く)に属する者は、国民健康保険の適用除外とされる。",a:true,e:"国保法6条9号。医療は生活保護の医療扶助で賄われる。",topic:"国民健康保険法"},
 {id:"X8-165",s:8,q:"後期高齢者医療の被保険者となった者であっても、国民健康保険の被保険者資格を喪失しない。",a:false,e:"国保法6条8号。後期高齢者医療の被保険者は国民健康保険の適用除外。",topic:"国民健康保険法"},
 {id:"X8-166",s:8,q:"国民健康保険の被保険者は、都道府県の区域内に住所を有しなくなった日の翌日に資格を喪失するが、その日に他の都道府県の区域内に住所を有するに至ったときは、その日に喪失する。",a:true,e:"国保法8条1項。",topic:"国民健康保険法"},
 {id:"X8-167",s:8,q:"国民健康保険組合を設立しようとするときは、組合員となる者300人以上の同意を得て、厚生労働大臣の認可を受けなければならない。",a:false,e:"国保法17条。認可するのは主たる事務所の所在地の都道府県知事。",topic:"国民健康保険法"},
 {id:"X8-168",s:8,q:"国民健康保険の傷病手当金は、市町村又は国民健康保険組合が条例又は規約で定めるところにより行うことができる任意給付である。",a:true,e:"国保法58条2項。出産育児一時金・葬祭費は原則として行う給付(相対的必要給付)。",topic:"国民健康保険法"},
 {id:"X8-169",s:8,q:"国民健康保険の出産育児一時金及び葬祭費は任意給付であり、市町村はこれを行うかどうかを自由に決めることができる。",a:false,e:"国保法58条1項。条例・規約の定めにより行うものとされ、特別の理由があるときに限り全部又は一部を行わないことができる。",topic:"国民健康保険法"},
 {id:"X8-170",s:8,q:"国民健康保険の療養の給付に係る一部負担金の割合は、6歳に達する日以後の最初の3月31日以前の被保険者については2割である。",a:true,e:"国保法42条1項。70歳以上は2割(現役並み所得者3割)、その他は3割。",topic:"国民健康保険法"},
 {id:"X8-171",s:8,q:"国民健康保険税の徴収権の消滅時効は、国民健康保険料と同じく2年である。",a:false,e:"保険料は国保法110条で2年。保険税は地方税法の規定により5年。",topic:"国民健康保険法"},
 {id:"X8-172",s:8,q:"国民健康保険の保険給付に関する処分に不服がある者は、国民健康保険審査会に審査請求をすることができ、国民健康保険審査会は各都道府県に置かれる。",a:true,e:"国保法91条・92条。保険料その他の徴収金に関する処分も対象。",topic:"国民健康保険法"},
 {id:"X8-173",s:8,q:"国民健康保険審査会は、被保険者を代表する委員、保険者を代表する委員及び公益を代表する委員各5人をもって組織する。",a:false,e:"国保法93条。各3人の計9人で組織する。",topic:"国民健康保険法"},
 {id:"X8-174",s:8,q:"修学のため他の市町村に住所を有する学生は、特例により、修学していないとすれば住所を有した市町村(親元)の国民健康保険の被保険者とされる。",a:true,e:"国保法116条(修学中の被保険者の特例)。",topic:"国民健康保険法"},
 {id:"X8-175",s:8,q:"都道府県は、市町村から国民健康保険事業費納付金を徴収し、市町村に対して保険給付に必要な費用を保険給付費等交付金として交付する。",a:true,e:"国保法75条の2・75条の7。平成30年度から都道府県が財政運営の責任主体。",topic:"国民健康保険法"},
 {id:"X8-176",s:8,q:"世帯主は、世帯に属する被保険者の資格の取得・喪失について、その事実があった日から30日以内に市町村に届け出なければならない。",a:false,e:"国保法9条・施行規則。14日以内に届け出る。",topic:"国民健康保険法"},
 {id:"X8-177",s:8,q:"病院等に入院・入所するため他の都道府県の区域内に住所を変更した国民健康保険の被保険者は、住所地特例により、従前の住所地の市町村等の被保険者とされる。",a:true,e:"国保法116条の2。",topic:"国民健康保険法"},
 {id:"X8-178",s:8,q:"国民健康保険の事業の運営に関する協議会は市町村に置かれるが、都道府県には置かれない。",a:false,e:"国保法11条。平成30年度から都道府県にも協議会が置かれている。",topic:"国民健康保険法"},
 {id:"X8-179",s:8,q:"国民健康保険の保険料について、未就学児に係る均等割額は、その5割が公費により軽減される。",a:true,e:"2022年4月施行の国保法改正による未就学児の均等割軽減。",topic:"国民健康保険法"},
 {id:"X8-180",s:8,q:"国民健康保険には、被保険者が出産する場合の産前産後期間の保険料の減額措置は設けられていない。",a:false,e:"2024年1月から、出産予定月の前月から4か月間(多胎は3か月前から6か月間)の所得割額・均等割額が免除される(産前産後期間の保険料軽減措置)。",topic:"国民健康保険法"},
 {id:"X8-181",s:8,q:"国民健康保険組合の組合員は、同種の事業又は業務に従事する者で、当該組合の地区内に住所を有するものとされる。",a:true,e:"国保法13条。",topic:"国民健康保険法"},
 {id:"X8-182",s:8,q:"市町村及び国民健康保険組合は、特別の理由がある被保険者で一部負担金を支払うことが困難と認められるものに対し、一部負担金の減額・免除等の措置をとることができる。",a:true,e:"国保法44条。震災・風水害等による財産の損害などが典型例。",topic:"国民健康保険法"},
 {id:"X8-183",s:8,q:"市町村は、療養の給付に関する費用の審査及び支払に関する事務を、全国健康保険協会に委託しなければならない。",a:false,e:"国保法45条5項。国民健康保険団体連合会又は社会保険診療報酬支払基金に委託することができる。",topic:"国民健康保険法"},
 {id:"X8-184",s:8,q:"後期高齢者医療は、都道府県の区域ごとに、その区域内のすべての市町村が加入して設ける後期高齢者医療広域連合が行う。",a:true,e:"高齢者医療確保法48条。",topic:"高齢者医療確保法"},
 {id:"X8-185",s:8,q:"後期高齢者医療の保険料は、後期高齢者医療広域連合が被保険者から直接徴収する。",a:false,e:"同法104条1項。保険料を徴収するのは市町村。広域連合は保険料を賦課する。",topic:"高齢者医療確保法"},
 {id:"X8-186",s:8,q:"生活保護法による保護を受けている世帯に属する75歳以上の者は、後期高齢者医療の被保険者とならない。",a:true,e:"同法51条。適用除外とされ、医療扶助の対象となる。",topic:"高齢者医療確保法"},
 {id:"X8-187",s:8,q:"都道府県医療費適正化計画は、5年を1期として定められる。",a:false,e:"同法9条。6年を1期とする(2018年度〜)。全国医療費適正化計画も6年1期。",topic:"高齢者医療確保法"},
 {id:"X8-188",s:8,q:"保険者は、特定健康診査等基本指針に即して、6年ごとに6年を1期とする特定健康診査等実施計画を定める。",a:true,e:"同法19条。",topic:"高齢者医療確保法"},
 {id:"X8-189",s:8,q:"後期高齢者医療の給付に要する費用は、公費と被保険者の保険料のみで賄われ、現役世代が加入する医療保険者の負担はない。",a:false,e:"公費約5割、医療保険者からの後期高齢者支援金約4割、被保険者の保険料約1割で賄われる。",topic:"高齢者医療確保法"},
 {id:"X8-190",s:8,q:"後期高齢者支援金は、社会保険診療報酬支払基金が各医療保険者から徴収し、後期高齢者医療広域連合に後期高齢者交付金として交付する。",a:true,e:"高齢者医療確保法。被用者保険の間では全面総報酬割が導入されている。",topic:"高齢者医療確保法"},
 {id:"X8-191",s:8,q:"前期高齢者に係る保険者間の費用負担の調整は、後期高齢者医療広域連合が行う。",a:false,e:"社会保険診療報酬支払基金が前期高齢者納付金を徴収し、前期高齢者交付金を交付して調整する。",topic:"高齢者医療確保法"},
 {id:"X8-192",s:8,q:"後期高齢者医療給付等に関する処分に不服がある者は、各都道府県に置かれる後期高齢者医療審査会に審査請求をすることができる。",a:true,e:"同法128条・129条。保険料その他の徴収金に関する処分も対象。",topic:"高齢者医療確保法"},
 {id:"X8-193",s:8,q:"後期高齢者医療の保険料率は、おおむね3年を通じ財政の均衡を保つことができるものでなければならない。",a:false,e:"同法104条3項。おおむね2年を通じ財政の均衡を保つことができるものでなければならない。",topic:"高齢者医療確保法"},
 {id:"X8-194",s:8,q:"後期高齢者医療の保険料は、被保険者均等割額と所得割額の合計額によって算定され、保険料率は後期高齢者医療広域連合の条例で定められる。",a:true,e:"同法104条・施行令。原則として広域連合内で均一の保険料率。",topic:"高齢者医療確保法"},
 {id:"X8-195",s:8,q:"特定保健指導は、特定健康診査の結果により健康の保持に努める必要がある者として厚生労働省令で定めるものに対し、保険者が行う。",a:true,e:"同法24条。動機付け支援・積極的支援がある。",topic:"高齢者医療確保法"},
 {id:"X8-196",s:8,q:"後期高齢者医療広域連合は、条例で定めるところにより葬祭費の支給又は葬祭の給付を行うが、特別の理由があるときはその全部又は一部を行わないことができる。",a:true,e:"同法86条1項。",topic:"高齢者医療確保法"},
 {id:"X8-197",s:8,q:"後期高齢者医療の被保険者が他の都道府県の特別養護老人ホームに入所して住所を移した場合、入所先の広域連合の被保険者となる。",a:false,e:"同法55条(住所地特例)。従前の住所地の広域連合の被保険者となる。",topic:"高齢者医療確保法"},
 {id:"X8-198",s:8,q:"要介護認定は、その申請のあった日にさかのぼってその効力を生ずる。",a:true,e:"介護保険法27条8項。申請日からサービスを利用できる根拠となる。",topic:"介護保険法"},
 {id:"X8-199",s:8,q:"市町村は、要介護認定の申請があったときは、申請のあった日から60日以内に処分をしなければならない。",a:false,e:"介護保険法27条11項。原則30日以内(特別な理由があるときは延期できる)。",topic:"介護保険法"},
 {id:"X8-200",s:8,q:"要介護更新認定の申請は、有効期間満了日の60日前から満了日までの間に行うことができる。",a:true,e:"介護保険法28条2項・施行規則。",topic:"介護保険法"},
 {id:"X8-201",s:8,q:"要介護更新認定の有効期間は、介護認定審査会の意見に基づき延長する場合でも、24か月が上限である。",a:false,e:"施行規則。更新認定は原則12か月で、3か月から48か月の範囲で定めることができる(2021年4月〜)。",topic:"介護保険法"},
 {id:"X8-202",s:8,q:"要介護認定を受けた被保険者が他の市町村に転居した場合、転入先の市町村に14日以内に従前の認定に関する書類を添えて申請すれば、審査判定を経ずに認定を受けることができる。",a:true,e:"介護保険法36条。",topic:"介護保険法"},
 {id:"X8-203",s:8,q:"介護保険の第2号被保険者の保険料は、市町村が普通徴収の方法により個別に徴収する。",a:false,e:"第2号の保険料は医療保険者が医療保険料と一体で徴収し、介護給付費・地域支援事業支援納付金として支払基金に納付する。",topic:"介護保険法"},
 {id:"X8-204",s:8,q:"介護保険の住宅改修費の支給限度基準額は、同一住宅・同一被保険者につき原則10万円である。",a:false,e:"厚生労働省告示。原則20万円(支給はその9割等)。年度10万円は特定福祉用具購入費の支給限度基準額。",topic:"介護保険法"},
 {id:"X8-205",s:8,q:"介護老人福祉施設(特別養護老人ホーム)への新規入所は、要介護1以上の者であれば原則として認められる。",a:false,e:"2015年4月から原則として要介護3以上。要介護1・2はやむを得ない事情がある場合の特例入所。",topic:"介護保険法"},
 {id:"X8-206",s:8,q:"居宅介護支援(ケアプランの作成等)に係る居宅介護サービス計画費は全額が保険給付され、利用者負担はない。",a:true,e:"介護保険法46条。10割給付。",topic:"介護保険法"},
 {id:"X8-207",s:8,q:"介護支援専門員証の有効期間は3年であり、更新研修を受けて更新する。",a:false,e:"介護保険法69条の7。有効期間は5年。介護支援専門員の登録は都道府県知事が行う。",topic:"介護保険法"},
 {id:"X8-208",s:8,q:"市町村は3年を1期とする市町村介護保険事業計画を、都道府県は3年を1期とする都道府県介護保険事業支援計画を定める。",a:true,e:"介護保険法117条・118条。第1号保険料も計画期間ごとに設定される。",topic:"介護保険法"},
 {id:"X8-209",s:8,q:"地域密着型サービス事業者の指定は、都道府県知事が行う。",a:false,e:"介護保険法78条の2。市町村長が指定する。居宅サービス事業者の指定は都道府県知事(指定都市・中核市は市長)。",topic:"介護保険法"},
 {id:"X8-210",s:8,q:"介護保険の保険給付は、労働者災害補償保険法等の規定により介護保険の給付に相当する給付を受けることができるときは、その限度で行われない。",a:true,e:"介護保険法20条。労災保険等の給付が優先する。",topic:"介護保険法"},
 {id:"X8-211",s:8,q:"要介護認定等の処分に対する審査請求は、市町村に置かれる介護認定審査会に対して行う。",a:false,e:"介護保険法183条・184条。都道府県に置かれる介護保険審査会に審査請求する。",topic:"介護保険法"},
 {id:"X8-212",s:8,q:"介護保険審査会への審査請求は、処分があったことを知った日の翌日から起算して3か月以内に、文書又は口頭でしなければならない。",a:true,e:"介護保険法192条。正当な理由があれば期間経過後でも可能。",topic:"介護保険法"},
 {id:"X8-213",s:8,q:"介護保険の保険給付に関する処分の取消しの訴えは、介護保険審査会に対する審査請求を経ることなく提起することができる。",a:false,e:"介護保険法196条。審査請求に対する裁決を経た後でなければ提起できない(審査請求前置)。",topic:"介護保険法"},
 {id:"X8-214",s:8,q:"財政安定化基金は、市町村の介護保険財政の安定化に資するため都道府県が設けるもので、その財源は国、都道府県及び市町村が3分の1ずつ負担する。",a:true,e:"介護保険法147条。市町村の負担分は第1号保険料を財源とする拠出金。",topic:"介護保険法"},
 {id:"X8-215",s:8,q:"介護保険の第2号被保険者であっても、一定以上の所得がある場合には、利用者負担が2割又は3割となる。",a:false,e:"2割・3割負担は第1号被保険者の一定以上所得者が対象。第2号被保険者は所得にかかわらず1割。",topic:"介護保険法"},
 {id:"X8-216",s:8,q:"第2号被保険者が保険給付を受けるには、要介護・要支援状態が特定疾病によって生じたものであることが必要であり、特定疾病は政令で16種類が定められている。",a:true,e:"介護保険法7条3項・施行令2条。末期がん、関節リウマチ、初老期における認知症等。",topic:"介護保険法"},
 {id:"X8-217",s:8,q:"地域包括支援センターは都道府県が設置するものであり、市町村は設置することができない。",a:false,e:"介護保険法115条の46。市町村が設置でき、包括的支援事業の委託を受けた法人も設置できる。",topic:"介護保険法"},
 {id:"X8-218",s:8,q:"市町村特別給付は、介護給付・予防給付のほかに市町村が条例で定めて行う給付であり、その費用は原則として第1号被保険者の保険料で賄われる。",a:true,e:"介護保険法62条。配食サービス等のいわゆる横出しサービス。",topic:"介護保険法"},
 {id:"X8-219",s:8,q:"介護保険の第1号被保険者の資格は、65歳の誕生日の翌日に取得する。",a:false,e:"年齢計算の原則により、65歳に達した日(誕生日の前日)に取得する。",topic:"介護保険法"},
 {id:"X8-220",s:8,q:"介護保険料を徴収する権利及び保険給付を受ける権利は、これらを行使することができる時から2年を経過したときは、時効によって消滅する。",a:true,e:"介護保険法200条1項。",topic:"介護保険法"},
 {id:"X8-221",s:8,q:"介護医療院は、介護療養型医療施設とともに2024年3月末で廃止された。",a:false,e:"介護医療院は2018年4月に創設された介護保険施設。2024年3月末で廃止されたのは介護療養型医療施設。",topic:"介護保険法"},
 {id:"X8-222",s:8,q:"船員保険の保険者は全国健康保険協会であり、協会には船舶所有者及び被保険者の意見を聴いて事業の円滑な運営を図るため、船員保険協議会が置かれる。",a:true,e:"船員保険法4条・6条。",topic:"船員保険法"},
 {id:"X8-223",s:8,q:"船員保険の被保険者は、船員法1条に規定する船員として船舶所有者に使用される者のうち、日本国籍を有する者に限られる。",a:false,e:"船員保険法2条。国籍要件はない。",topic:"船員保険法"},
 {id:"X8-224",s:8,q:"船員保険の被保険者が職務上の事由により1か月以上行方不明となったときは、その被扶養者に対し行方不明手当金が支給される。",a:true,e:"船員保険法独自の給付。支給期間は3か月が限度。",topic:"船員保険法"},
 {id:"X8-225",s:8,q:"船員保険の疾病任意継続被保険者となるには、資格喪失日の前日まで継続して1年以上被保険者であったことが必要である。",a:false,e:"船員保険法2条2項。継続して2か月以上。資格喪失日から20日以内に申し出る。",topic:"船員保険法"},
 {id:"X8-226",s:8,q:"船員保険の保険料は、疾病保険料率と災害保健福祉保険料率を合算した率により算定され、介護保険第2号被保険者はこれに介護保険料率が加算される。",a:true,e:"船員保険法。職務上の年金部門等は2010年に労災保険・雇用保険に統合された。",topic:"船員保険法"},
 {id:"X8-227",s:8,q:"特定社会保険労務士が単独で紛争解決手続代理業務を行うことができる民間紛争解決手続は、紛争の目的の価額が60万円を超えないものに限られる。",a:false,e:"社労士法2条1項1号の6。上限は120万円で、超える場合は弁護士との共同受任が必要。",topic:"社会保険労務士法"},
 {id:"X8-228",s:8,q:"社会保険労務士は、労務管理や労働社会保険諸法令に関する事項について、裁判所において、補佐人として弁護士である訴訟代理人とともに出頭し、陳述をすることができる。",a:true,e:"社労士法2条の2(2015年4月施行)。当事者等が直ちに取り消し・更正しない限り当事者等の陳述とみなされる。",topic:"社会保険労務士法"},
 {id:"X8-229",s:8,q:"社会保険労務士となる資格を有する者が社会保険労務士となるには、厚生労働大臣の登録を受けなければならない。",a:false,e:"社労士法14条の2。全国社会保険労務士会連合会に備える社会保険労務士名簿への登録を受ける。",topic:"社会保険労務士法"},
 {id:"X8-230",s:8,q:"社会保険労務士法人は、社員が1人でも設立することができる。",a:true,e:"2016年1月から1人法人が認められている。社員は社会保険労務士に限られる。",topic:"社会保険労務士法"},
 {id:"X8-231",s:8,q:"開業社会保険労務士は、業務に関する帳簿を関係書類とともに帳簿閉鎖の時から5年間保存しなければならない。",a:false,e:"社労士法19条。保存期間は2年間。",topic:"社会保険労務士法"},
 {id:"X8-232",s:8,q:"社会保険労務士は、社会保険労務士の信用又は品位を害するような行為をしてはならない。",a:true,e:"社労士法16条(信用失墜行為の禁止)。違反は懲戒の対象となる。",topic:"社会保険労務士法"},
 {id:"X8-233",s:8,q:"社会保険労務士が申請書等を作成した場合でも、その申請書等に社会保険労務士である旨を付記し記名することは求められていない。",a:false,e:"社労士法17条。作成した申請書等には、社会保険労務士である旨を付記して記名しなければならない。",topic:"社会保険労務士法"},
 {id:"X8-234",s:8,q:"社会保険労務士は、正当な理由がなくて、業務に関して知り得た秘密を他に漏らし又は盗用してはならず、社会保険労務士でなくなった後も同様である。",a:true,e:"社労士法21条。違反には罰則がある。",topic:"社会保険労務士法"},
 {id:"X8-235",s:8,q:"社会保険労務士は、社会保険労務士法27条の規定に違反する者から事件のあっせんを受けることができる。",a:false,e:"社労士法23条の2(非社会保険労務士との提携の禁止)。事件のあっせんを受け、又は自己の名義を利用させてはならない。",topic:"社会保険労務士法"},
 {id:"X8-236",s:8,q:"厚生労働大臣は、社会保険労務士に対し懲戒処分をしようとするときは、聴聞を行わなければならない。",a:true,e:"社労士法25条の4。行政手続法上の手続の区分にかかわらず聴聞を行う。",topic:"社会保険労務士法"},
 {id:"X8-237",s:8,q:"紛争解決手続代理業務には、紛争解決手続の係属中に行う和解の交渉や和解契約の締結の代理は含まれない。",a:false,e:"社労士法2条3項。相談、係属中の和解の交渉、和解契約の締結の代理も紛争解決手続代理業務に含まれる。",topic:"社会保険労務士法"},
 {id:"X8-238",s:8,q:"特定社会保険労務士でない社会保険労務士は、紛争調整委員会のあっせんの手続について、紛争の当事者を代理することはできない。",a:true,e:"社労士法2条2項。紛争解決手続代理業務は特定社会保険労務士に限り行える。",topic:"社会保険労務士法"},
 {id:"X8-239",s:8,q:"特定社会保険労務士は、都道府県労働委員会が行う個別労働関係紛争のあっせんの手続については、当事者を代理することができない。",a:false,e:"社労士法2条1項1号の5。都道府県労働委員会が行う個別労働関係紛争のあっせんも代理できる。",topic:"社会保険労務士法"},
 {id:"X8-240",s:8,q:"社会保険労務士は、登録を受けた時に、当然にその事務所の所在地の区域に設立されている社会保険労務士会の会員となる。",a:true,e:"社労士法(社会保険労務士会の会員に関する規定)。登録を受けた時に当然に会員となる、いわゆる当然入会制。",topic:"社会保険労務士法"},
 {id:"X8-241",s:8,q:"懲戒処分により失格処分を受けた者は、その処分を受けた日から5年を経過しなければ社会保険労務士となる資格を有しない。",a:false,e:"社労士法5条。失格処分を受けた日から3年を経過しない者が欠格事由に当たる。",topic:"社会保険労務士法"},
 {id:"X8-242",s:8,q:"開業社会保険労務士又は社会保険労務士法人の使用人その他の従業者は、正当な理由がなくて、業務に関して知り得た秘密を他に漏らし、又は盗用してはならない。",a:true,e:"社労士法27条の2。従業者でなくなった後も同様。",topic:"社会保険労務士法"},
 {id:"X8-243",s:8,q:"社会保険労務士試験は、厚生労働大臣が毎年2回以上行う。",a:false,e:"社労士法10条。毎年1回以上行う。試験事務は全国社会保険労務士会連合会に委託できる。",topic:"社会保険労務士法"},
 {id:"X8-244",s:8,q:"確定給付企業年金を実施しようとする事業主は、厚生年金保険の被保険者の過半数で組織する労働組合(ないときは過半数代表者)の同意を得て規約を作成しなければならない。",a:true,e:"確定給付企業年金法3条1項。",topic:"確定給付企業年金法"},
 {id:"X8-245",s:8,q:"規約型企業年金の規約は厚生労働大臣の認可を、企業年金基金の設立は厚生労働大臣の承認を受けなければならない。",a:false,e:"DB法3条・4条。規約型は規約の「承認」、基金型は基金設立の「認可」。逆になっている。",topic:"確定給付企業年金法"},
 {id:"X8-246",s:8,q:"老齢給付金は、60歳以上70歳以下の規約で定める年齢に達したとき、又は50歳以上その年齢未満の規約で定める年齢で退職したときに支給される。",a:true,e:"DB法36条2項。",topic:"確定給付企業年金法"},
 {id:"X8-247",s:8,q:"規約において、30年を超える加入者期間を老齢給付金の支給要件として定めることができる。",a:false,e:"DB法36条4項。20年を超える加入者期間を要件として定めてはならない。",topic:"確定給付企業年金法"},
 {id:"X8-248",s:8,q:"確定給付企業年金の年金給付は、終身又は5年以上にわたり、毎年1回以上定期的に支給するものでなければならない。",a:true,e:"DB法33条。",topic:"確定給付企業年金法"},
 {id:"X8-249",s:8,q:"規約において、5年を超える加入者期間を脱退一時金の支給要件として定めることができる。",a:false,e:"DB法41条3項。3年を超える加入者期間を要件として定めてはならない。",topic:"確定給付企業年金法"},
 {id:"X8-250",s:8,q:"確定給付企業年金の掛金は原則として事業主が拠出するが、規約で定めるところにより加入者が掛金の一部を負担することもでき、その場合は加入者本人の同意が必要である。",a:true,e:"DB法55条2項。加入者負担は掛金の2分の1を超えないこと等の要件がある。",topic:"確定給付企業年金法"},
 {id:"X8-251",s:8,q:"確定給付企業年金の掛金の額は、少なくとも10年ごとに再計算しなければならない。",a:false,e:"DB法58条1項。少なくとも5年ごとに再計算しなければならない(財政再計算)。",topic:"確定給付企業年金法"},
 {id:"X8-252",s:8,q:"企業年金基金には代議員会が置かれ、代議員はすべて加入者の互選により選出される。",a:false,e:"DB法18条。代議員の半数は事業主が選定し、残りの半数は加入者が互選する。",topic:"確定給付企業年金法"},
 {id:"X8-253",s:8,q:"確定給付企業年金において、障害給付金及び遺族給付金は必ず支給しなければならない給付である。",a:false,e:"DB法29条。老齢給付金・脱退一時金は必須、障害給付金・遺族給付金は規約で定めた場合に行う任意の給付。",topic:"確定給付企業年金法"},
 {id:"X8-254",s:8,q:"確定給付企業年金の加入者は実施事業所に使用される厚生年金保険の被保険者であるが、規約で一定の加入資格を定めた場合、その資格を有しない者は加入者とならない。",a:true,e:"DB法25条。資格は特定の者に不当に差別的なものであってはならない。",topic:"確定給付企業年金法"},
 {id:"X8-255",s:8,q:"個人型確定拠出年金は、国民年金基金連合会が実施する。",a:true,e:"確定拠出年金法55条。企業型は事業主が厚生労働大臣の承認を受けた規約に基づき実施する。",topic:"確定拠出年金法"},
 {id:"X8-256",s:8,q:"企業型確定拠出年金の加入者となることができるのは、60歳未満の厚生年金保険の被保険者に限られる。",a:false,e:"2022年5月から70歳未満の厚生年金保険の被保険者に拡大(規約で一定の資格を定めることは可)。",topic:"確定拠出年金法"},
 {id:"X8-257",s:8,q:"個人型確定拠出年金の掛金は月額5,000円以上1,000円単位で加入者が定め、年単位でまとめて拠出することもできる。",a:true,e:"確定拠出年金法施行令。拠出限度額は加入者の区分ごとに異なる。",topic:"確定拠出年金法"},
 {id:"X8-258",s:8,q:"国民年金の第1号被保険者の個人型確定拠出年金の拠出限度額は、国民年金基金の掛金とは別枠で月額68,000円である。",a:false,e:"国民年金基金の掛金又は付加保険料と合算して月額68,000円。",topic:"確定拠出年金法"},
 {id:"X8-259",s:8,q:"企業年金等に加入していない第2号被保険者の個人型確定拠出年金の拠出限度額は月額23,000円であり、第3号被保険者も月額23,000円である。",a:true,e:"確定拠出年金法69条・施行令。公務員は月額20,000円(2024年12月〜)。",topic:"確定拠出年金法"},
 {id:"X8-260",s:8,q:"確定給付企業年金に加入している会社員の個人型確定拠出年金の拠出限度額は、2026年4月時点で月額12,000円である。",a:false,e:"2024年12月から月額20,000円(企業型DC・DB等の事業主掛金相当額との合計で月額55,000円以内)。",topic:"確定拠出年金法"},
 {id:"X8-261",s:8,q:"運営管理機関は、35本以下の範囲で、リスク・リターン特性の異なる3以上の運用の方法を選定し、加入者等に提示しなければならない。",a:true,e:"確定拠出年金法23条・施行令。元本確保型の提示義務は2018年改正で廃止された。",topic:"確定拠出年金法"},
 {id:"X8-262",s:8,q:"確定拠出年金の老齢給付金は、60歳時点で通算加入者等期間が10年に満たない場合には支給されない。",a:false,e:"確定拠出年金法33条。期間に応じて61歳から65歳までの間で受給開始可能となる(8年以上は61歳…1か月以上は65歳)。",topic:"確定拠出年金法"},
 {id:"X8-263",s:8,q:"確定拠出年金の老齢給付金は、75歳に達するまでの間に受給を開始することができる。",a:true,e:"2022年4月から、受給開始時期の上限が70歳から75歳に拡大された。",topic:"確定拠出年金法"},
 {id:"X8-264",s:8,q:"企業型確定拠出年金では、勤続期間が5年未満の加入者が資格を喪失した場合に、事業主掛金相当分を事業主に返還させる旨を規約で定めることができる。",a:false,e:"確定拠出年金法3条3項。返還を定めることができるのは勤続3年未満の者。",topic:"確定拠出年金法"},
 {id:"X8-265",s:8,q:"企業型確定拠出年金を実施する事業主は、加入者等に対し、資産の運用に関する基礎的な資料の提供その他の必要な措置を継続的に講ずるよう努めなければならない。",a:true,e:"確定拠出年金法22条(投資教育)。",topic:"確定拠出年金法"},
 {id:"X8-266",s:8,q:"簡易型確定拠出年金は、使用する厚生年金保険の被保険者が300人以下の事業主が、設立手続等を簡素化して実施できる企業型年金である。",a:true,e:"2020年10月に対象が100人以下から300人以下に拡大された。",topic:"確定拠出年金法"},
 {id:"X8-267",s:8,q:"中小事業主掛金納付制度(iDeCo+)は、企業型確定拠出年金を実施している中小事業主が、iDeCo加入者の掛金に上乗せして掛金を拠出する制度である。",a:false,e:"確定拠出年金法68条の2。企業年金(企業型DC・DB等)を実施していない300人以下の事業主が対象。",topic:"確定拠出年金法"},
 {id:"X8-268",s:8,q:"企業型確定拠出年金の拠出限度額は、確定給付企業年金等の他制度を実施していない場合、月額55,000円である。",a:true,e:"他制度を併用する場合は、55,000円から他制度の掛金相当額を控除した額(2024年12月〜)。",topic:"確定拠出年金法"},
 {id:"X8-269",s:8,q:"国民年金の任意加入被保険者は、個人型確定拠出年金に加入することができない(2026年4月時点)。",a:false,e:"2022年5月から、国民年金の任意加入被保険者も個人型確定拠出年金に加入できる。",topic:"確定拠出年金法"},
 {id:"X8-270",s:8,q:"確定拠出年金の個人別管理資産は、障害や死亡の場合を除き、原則として60歳前に引き出すことはできない。",a:true,e:"脱退一時金は、資産額が少額であること等の要件を満たす場合に限り例外的に認められる。",topic:"確定拠出年金法"},
 {id:"X8-271",s:8,q:"企業型確定拠出年金の規約は、厚生労働大臣の認可を受けることにより効力を生ずる。",a:false,e:"確定拠出年金法3条1項。規約について厚生労働大臣の「承認」を受ける。",topic:"確定拠出年金法"},
 {id:"X8-272",s:8,q:"児童手当法における児童とは、18歳に達する日以後の最初の3月31日までの間にある者であって、原則として日本国内に住所を有するものをいう。",a:true,e:"児童手当法3条1項。留学中の者は一定の要件で国内住所がなくても対象となる。",topic:"児童手当法"},
 {id:"X8-273",s:8,q:"3歳以上高校生年代までの第1子・第2子に係る児童手当の額は、児童1人につき月額15,000円である(2026年4月時点)。",a:false,e:"月額10,000円。3歳未満の第1子・第2子は15,000円、第3子以降は年齢を問わず30,000円(2024年10月〜)。",topic:"児童手当法"},
 {id:"X8-274",s:8,q:"児童手当の支給は、受給資格者が認定の請求をした日の属する月の翌月から始め、支給すべき事由が消滅した日の属する月で終わる。",a:true,e:"児童手当法8条2項。",topic:"児童手当法"},
 {id:"X8-275",s:8,q:"児童手当は、毎年2月、6月及び10月の年3回、それぞれの前月までの分が支払われる(2026年4月時点)。",a:false,e:"2024年10月改正で、偶数月(2・4・6・8・10・12月)の年6回、各前月までの分を支払うこととされた。",topic:"児童手当法"},
 {id:"X8-276",s:8,q:"受給資格者が出生等の日の翌日から15日以内に認定の請求をしたときは、出生等の日の属する月の翌月から児童手当が支給される。",a:true,e:"児童手当法8条3項(15日特例)。",topic:"児童手当法"},
 {id:"X8-277",s:8,q:"公務員である受給資格者に係る児童手当の認定は、住所地の市町村長が行う。",a:false,e:"児童手当法17条。公務員は所属庁の長等が認定し支給する。",topic:"児童手当法"},
 {id:"X8-278",s:8,q:"児童福祉施設等に入所している児童については、その児童の父母に対して児童手当が支給される。",a:false,e:"児童手当法4条1項4号。施設入所児童については、施設の設置者等に支給される。",topic:"児童手当法"},
 {id:"X8-279",s:8,q:"第3子以降の加算の算定に当たり、兄姉として数えられるのは18歳到達年度末までの児童に限られる(2026年4月時点)。",a:false,e:"2024年10月から、親等が経済的負担をしている22歳到達年度末までの者も兄姉として数える。",topic:"児童手当法"},
 {id:"X8-280",s:8,q:"児童手当の額が増額となる改定は、改定後の額についての認定の請求をした日の属する月の翌月から行う。",a:true,e:"児童手当法9条1項。減額となる改定は、事由が生じた日の属する月の翌月から行う(同条3項)。",topic:"児童手当法"},
 {id:"X8-281",s:8,q:"児童手当の支給を受ける権利は、5年を経過したときは時効によって消滅する。",a:false,e:"児童手当法。支給を受ける権利の時効は2年。",topic:"児童手当法"},
 {id:"X8-282",s:8,q:"社会保険審査官は、厚生労働省の職員のうちから厚生労働大臣が命じ、各地方厚生局(地方厚生支局を含む)に置かれる。",a:true,e:"社会保険審査官及び社会保険審査会法1条・2条。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-283",s:8,q:"社会保険審査官に対する審査請求は、原処分があったことを知った日の翌日から起算して60日以内にしなければならない。",a:false,e:"同法4条1項。3か月以内。正当な事由があれば期間経過後も可。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-284",s:8,q:"社会保険審査会への再審査請求は、社会保険審査官の決定書の謄本が送付された日の翌日から起算して2か月以内にしなければならない。",a:true,e:"同法32条1項。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-285",s:8,q:"社会保険審査官に審査請求をした日から3か月以内に決定がないときは、審査請求人は、審査官が審査請求を棄却したものとみなすことができる。",a:false,e:"健康保険法189条2項等。2か月以内に決定がないときに棄却とみなし、再審査請求ができる。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-286",s:8,q:"健康保険の保険料等の賦課又は徴収の処分に不服がある者は、社会保険審査官を経ずに、直接社会保険審査会に審査請求をすることができる。",a:true,e:"健康保険法190条。被保険者資格・標準報酬・保険給付の処分は審査官→審査会の二審制。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-287",s:8,q:"社会保険審査会は、委員長及び委員3人をもって組織する。",a:false,e:"同法19条・21条。委員長及び委員5人(計6人)。両議院の同意を得て厚生労働大臣が任命し、任期は3年。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-288",s:8,q:"社会保険審査官に対する審査請求は、文書又は口頭ですることができ、代理人によってすることもできる。",a:true,e:"同法5条・5条の2。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-289",s:8,q:"審査請求があったときは、原処分の執行は当然に停止される。",a:false,e:"同法10条。原処分の執行は停止されない。審査官は必要があると認めるときは執行を停止できる。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-290",s:8,q:"社会保険審査会における再審査請求の審理は公開して行われるが、当事者の申立てがあったときは公開しないことができる。",a:true,e:"同法37条。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-291",s:8,q:"国民健康保険法による保険給付に関する処分は、社会保険審査官に対する審査請求の対象となる。",a:false,e:"国保の処分は都道府県の国民健康保険審査会が扱う。審査官・審査会は健保、船保、厚年、国年等を扱う。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-292",s:8,q:"健康保険法による保険給付に関する処分の取消しの訴えは、当該処分についての審査請求に対する社会保険審査官の決定を経た後でなければ提起することができない。",a:true,e:"健康保険法192条(審査請求前置)。2016年改正で再審査請求の裁決までは不要となった。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-293",s:8,q:"社会保険審査官に対する審査請求は、時効の完成猶予及び更新に関しては裁判上の請求とはみなされない。",a:false,e:"健康保険法189条4項等。審査請求は、時効の完成猶予及び更新に関しては裁判上の請求とみなされる。",topic:"社会保険審査官及び社会保険審査会法"},
 {id:"X8-294",s:8,q:"介護保険法は1997年(平成9年)に制定され、2000年(平成12年)4月に施行された。",a:true,e:"市町村を保険者とする社会保険方式で2000年4月にスタートした。",topic:"沿革"},
 {id:"X8-295",s:8,q:"国民皆保険・皆年金体制は、1973年(昭和48年)に実現した。",a:false,e:"1961年(昭和36年)4月に実現。1973年は老人医療費の無料化などで「福祉元年」と呼ばれる。",topic:"沿革"},
 {id:"X8-296",s:8,q:"2008年(平成20年)4月、老人保健法が高齢者の医療の確保に関する法律に改められ、後期高齢者医療制度が創設された。",a:true,e:"同時に特定健康診査・特定保健指導が保険者に義務付けられた。",topic:"沿革"},
 {id:"X8-297",s:8,q:"健康保険法は、1947年(昭和22年)に労働基準法と同時に制定された。",a:false,e:"健康保険法は1922年(大正11年)制定、1927年(昭和2年)全面施行。わが国最初の社会保険立法。",topic:"沿革"},
 {id:"X8-298",s:8,q:"確定拠出年金法は2001年(平成13年)10月に施行され、確定給付企業年金法は2002年(平成14年)4月に施行された。",a:true,e:"いずれも2001年(平成13年)に制定された。",topic:"沿革"},
 {id:"X8-299",s:8,q:"旧国民健康保険法は、1958年(昭和33年)に初めて制定された。",a:false,e:"旧国民健康保険法は1938年(昭和13年)制定。1958年に現行の国民健康保険法が制定され、1961年に全市町村で実施。",topic:"沿革"},
 {id:"X8-300",s:8,q:"児童手当法は、2000年(平成12年)の介護保険法の施行と同時に制定された。",a:false,e:"児童手当法は1971年(昭和46年)に制定され、1972年(昭和47年)に施行された。",topic:"沿革"},
 {id:"XT8-01",s:8,format:"choice",examFmt:true,topic:"労働者派遣法",difficulty:3,q:"労働者派遣法に関する次の記述のうち、正しいものはどれか。",choices:[{t:"港湾運送業務については、紹介予定派遣に限り労働者派遣事業を行うことができる。",ok:0,why:"誤り。港湾運送・建設・警備は例外なく禁止(4条1項)。紹介予定派遣等の例外があるのは医療関係業務。"},{t:"労働者派遣事業の許可の有効期間は、更新後も3年である。",ok:0,why:"誤り。新規は3年、更新後は5年(10条)。"},{t:"派遣元事業主に無期雇用される派遣労働者は、派遣先の事業所単位・個人単位の期間制限の対象とならない。",ok:1,why:"正しい。無期雇用派遣労働者や60歳以上の者等は期間制限の対象外(40条の2第1項)。"},{t:"派遣元管理台帳は、労働者派遣の終了の日から1年間保存すれば足りる。",ok:0,why:"誤り。3年間保存(37条2項)。派遣先管理台帳も3年。"},{t:"紹介予定派遣における派遣就業の期間は、同一の派遣労働者について1年を超えてはならない。",ok:0,why:"誤り。6か月を超えてはならない(派遣元指針)。"}],memoryPoint:"禁止3業務は例外なし。許可は新規3年・更新5年。無期雇用・60歳以上は期間制限なし。台帳3年。紹介予定派遣は6か月。",trap:"紹介予定派遣の6か月や台帳の3年を1年にずらす改変、医療関係業務の例外を港湾運送に付け替える形が狙われる。",e:"無期雇用派遣労働者は期間制限の対象外(派遣法40条の2)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-02",s:8,format:"choice",examFmt:true,topic:"職業安定法",difficulty:3,q:"職業安定法に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"学校は、厚生労働大臣に届け出て、無料の職業紹介事業を行うことができる。",ok:0,why:"正しい。学校等は届出制(33条の2)。"},{t:"有料職業紹介事業者は、原則として求職者から手数料を徴収してはならない。",ok:0,why:"正しい。芸能家・モデル・年収700万円超の経営管理者等は例外(32条の3)。"},{t:"労働組合等は、厚生労働大臣の許可を受けて、無料の労働者供給事業を行うことができる。",ok:0,why:"正しい(45条)。有料では行えない。"},{t:"被用者以外の者に報酬を与えずに労働者の募集に従事させようとするときは、厚生労働大臣の許可を受けなければならない。",ok:1,why:"誤り。報酬を与えない委託募集は届出(36条3項)。許可が必要なのは報酬を与える場合(同条1項)。"},{t:"有料職業紹介事業の許可の有効期間は、新規が3年、更新後が5年である。",ok:0,why:"正しい(32条の6)。"}],memoryPoint:"学校は届出、一般の無料・有料紹介は許可。委託募集は報酬ありで許可・なしで届出。労働者供給は労働組合の無料のみ。",trap:"委託募集の許可と届出を入れ替える改変。報酬の有無で区別する。",e:"報酬を与えない委託募集は届出制(職安法36条3項)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-03",s:8,format:"choice",examFmt:true,topic:"高年齢者雇用安定法",difficulty:3,q:"高年齢者雇用安定法に関する次の記述のうち、正しいものはどれか。",choices:[{t:"事業主が定年を定める場合、その定年は65歳を下回ることができない。",ok:0,why:"誤り。60歳を下回ることができない(8条)。65歳までは雇用確保措置(9条)。"},{t:"70歳までの就業確保措置を講ずることは、事業主の義務である。",ok:0,why:"誤り。努力義務(10条の2)。"},{t:"高年齢者雇用状況等報告は、毎年4月1日現在の状況について行う。",ok:0,why:"誤り。毎年6月1日現在の状況を報告する。"},{t:"多数離職の届出は、1か月以内に30人以上の高年齢者等が離職する場合に必要となる。",ok:0,why:"誤り。高年法の多数離職届は5人以上(16条)。30人は労働施策総合推進法の大量雇用変動届。"},{t:"継続雇用制度には、特殊関係事業主が定年後の高年齢者を引き続いて雇用する制度も含まれる。",ok:1,why:"正しい(9条2項)。グループ会社での継続雇用も認められる。"}],memoryPoint:"定年は60歳以上、65歳までは義務、70歳までは努力義務。報告は6月1日現在。多数離職届は5人。",trap:"高年法の5人と労働施策総合推進法の30人、60歳と65歳を入れ替える改変。",e:"特殊関係事業主による継続雇用も可(高年法9条2項)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-04",s:8,format:"choice",examFmt:true,topic:"障害者雇用促進法",difficulty:3,q:"障害者雇用促進法に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"事業主は、障害者である労働者に対し、過重な負担を及ぼす場合を除き、障害の特性に配慮した必要な措置を講じなければならない。",ok:0,why:"正しい(36条の3)。"},{t:"実雇用率の算定において、週所定労働時間10時間以上20時間未満の知的障害者(重度でない者)は0.5人と算定される。",ok:1,why:"誤り。10時間以上20時間未満で0.5人と算定されるのは、重度身体・重度知的・精神障害者に限られる(2024年4月〜)。"},{t:"障害者を5人以上雇用する事業所では、障害者職業生活相談員を選任しなければならない。",ok:0,why:"正しい(79条)。"},{t:"障害者である労働者を解雇する場合は、原則としてその旨を公共職業安定所長に届け出なければならない。",ok:0,why:"正しい(81条)。"},{t:"差別禁止・合理的配慮の対象となる障害者は、障害者手帳の所持者に限られない。",ok:0,why:"正しい。2条1号の定義による。"}],memoryPoint:"短時間(10〜20時間)の0.5カウントは重度・精神のみ。相談員は5人以上。解雇は届出。手帳がなくても差別禁止の対象。",trap:"10〜20時間カウントの対象を障害の種類を問わないものに広げる改変。",e:"週10〜20時間の0.5カウントは重度身体・重度知的・精神障害者のみ。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-05",s:8,format:"choice",examFmt:true,topic:"パートタイム・有期雇用労働法",difficulty:3,q:"パートタイム・有期雇用労働法に関する次の記述のうち、正しいものはどれか。",choices:[{t:"短時間労働者に当たるかどうかは、事業所単位で通常の労働者と所定労働時間を比較して判断する。",ok:0,why:"誤り。同一の事業主に雇用される通常の労働者と比較する(2条1項)。"},{t:"事業主は、短時間・有期雇用労働者から求めがあったときは、通常の労働者との待遇の相違の内容及び理由を説明しなければならない。",ok:1,why:"正しい(14条2項)。"},{t:"昇給・退職手当・賞与の有無等を文書で明示しなかった事業主には、罰金が科される。",ok:0,why:"誤り。10万円以下の過料(31条)であり、刑罰の罰金ではない。"},{t:"短時間・有期雇用管理者の選任は、常時10人以上を雇用する事業所の事業主の義務である。",ok:0,why:"誤り。努力義務(17条)。"},{t:"通常の労働者への転換を推進するための措置を講ずることは、努力義務である。",ok:0,why:"誤り。いずれかの措置を講じなければならない(13条)。"}],memoryPoint:"比較は同一事業主単位。待遇差の説明義務あり。明示義務違反は過料10万円。管理者は努力義務、転換措置は義務。",trap:"過料と罰金、義務と努力義務を入れ替える改変。",e:"待遇差の内容・理由の説明義務(パート有期法14条2項)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-06",s:8,format:"choice",examFmt:true,topic:"労働関係調整法",difficulty:3,q:"労働関係調整法に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"公益事業の争議行為は、少なくとも10日前までに労働委員会及び厚生労働大臣又は都道府県知事に通知しなければならない。",ok:0,why:"正しい(37条)。"},{t:"緊急調整の決定の公表があったときは、公表の日から50日間は争議行為をすることができない。",ok:0,why:"正しい(38条)。"},{t:"労働委員会による調停は、関係当事者の双方から申請があった場合に限り開始される。",ok:1,why:"誤り。公益事業では一方からの申請や労働委員会の職権による開始もあり、労働協約の定めによる一方の申請でも開始される(18条)。"},{t:"安全保持の施設の正常な維持又は運行を停廃する行為は、争議行為としてでもすることができない。",ok:0,why:"正しい(36条)。"},{t:"内閣総理大臣は、緊急調整の決定をするときは、あらかじめ中央労働委員会の意見を聴かなければならない。",ok:0,why:"正しい(35条の2第2項)。"}],memoryPoint:"公益事業は10日前通知、緊急調整は50日間禁止、安全保持施設の停廃は不可。調停は公益事業なら一方申請でも開始。",trap:"斡旋・調停・仲裁の開始要件の混同。仲裁は双方申請か協約の定めによる申請が原則。",e:"調停は双方申請に限られない(労調法18条)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-07",s:8,format:"choice",examFmt:true,topic:"賃金支払確保法",difficulty:3,q:"賃金の支払の確保等に関する法律に関する次の記述のうち、正しいものはどれか。",choices:[{t:"退職した労働者の賃金に係る遅延利息の率は、年6%である。",ok:0,why:"誤り。年14.6%(6条1項)。"},{t:"退職手当についても、退職日までに支払わなければ年14.6%の遅延利息が生じる。",ok:0,why:"誤り。退職手当は対象外(6条1項括弧書)。"},{t:"未払賃金の立替払の額は、未払賃金総額の100分の80(退職日の年齢に応じた上限あり)である。",ok:1,why:"正しい(施行令4条)。"},{t:"立替払の対象となる未払賃金には、賞与が含まれる。",ok:0,why:"誤り。定期賃金と退職手当に限られる。"},{t:"退職手当の保全措置は、事業主の罰則付きの義務である。",ok:0,why:"誤り。努力義務(5条)。"}],memoryPoint:"遅延利息は年14.6%(退職手当は除く)。立替払は8割で賞与は対象外。退職手当の保全は努力義務。",trap:"14.6%と6%、退職手当の扱い、賞与の扱いを入れ替える改変。",e:"立替払は未払賃金総額の80%(年齢別上限あり)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-08",s:8,format:"choice",examFmt:true,topic:"労働施策総合推進法",difficulty:3,q:"労働施策総合推進法に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"職場のパワーハラスメントは、優越的な関係を背景とした言動、業務上必要かつ相当な範囲を超えたもの、就業環境が害されるものという3つの要素で定義される。",ok:0,why:"正しい(30条の2第1項)。"},{t:"労働者がパワーハラスメントの相談をしたことを理由とする不利益取扱いは禁止される。",ok:0,why:"正しい(30条の2第2項)。"},{t:"外国人雇用状況の届出は、特別永住者についても行わなければならない。",ok:1,why:"誤り。特別永住者は届出の対象外(28条)。"},{t:"事業主は、厚生労働省令で定める場合を除き、募集・採用について年齢にかかわりなく均等な機会を与えなければならない。",ok:0,why:"正しい(9条)。"},{t:"1の事業所で1か月以内に30人以上の労働者が経済的事情等により離職する場合は、大量雇用変動の届出が必要である。",ok:0,why:"正しい(27条)。"}],memoryPoint:"パワハラは3要素、相談による不利益取扱い禁止。外国人雇用状況届出は特別永住者を除く。大量雇用変動は30人以上。",trap:"外国人雇用状況の届出対象に特別永住者を含める改変。",e:"特別永住者は外国人雇用状況届出の対象外(同法28条)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-09",s:8,format:"choice",examFmt:true,topic:"個別労働紛争解決促進法",difficulty:3,q:"個別労働関係紛争の解決の促進に関する法律に関する次の記述のうち、正しいものはどれか。",choices:[{t:"個別労働関係紛争のあっせんは、都道府県労働委員会に置かれる紛争調整委員会が行う。",ok:0,why:"誤り。紛争調整委員会は都道府県労働局に置かれる(6条)。"},{t:"募集及び採用に関する紛争は、都道府県労働局長の助言・指導の対象とならない。",ok:0,why:"誤り。助言・指導の対象にはなる。あっせんの対象外である(5条)。"},{t:"あっせんは、紛争調整委員会の委員全員で行う。",ok:0,why:"誤り。会長が事件ごとに指名する3人のあっせん委員が行う(12条)。"},{t:"あっせんの打切りの通知を受けた日から30日以内に訴えを提起したときは、時効の完成猶予に関し、あっせんの申請の時に訴えの提起があったものとみなされる。",ok:1,why:"正しい(16条)。"},{t:"都道府県労働局長に紛争解決の援助を求めたことを理由とする不利益取扱いの禁止は、努力義務にとどまる。",ok:0,why:"誤り。解雇その他不利益な取扱いをしてはならない(4条3項)。"}],memoryPoint:"紛争調整委員会は都道府県労働局。募集・採用はあっせんの対象外。あっせん委員は3人。打切り後30日以内に提訴。",trap:"都道府県労働局と都道府県労働委員会を取り違えさせる改変。",e:"あっせん打切り後30日以内の提訴で時効の完成猶予(同法16条)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-10",s:8,format:"choice",examFmt:true,topic:"次世代法・女性活躍推進法",difficulty:3,q:"次世代育成支援対策推進法及び女性活躍推進法に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"次世代法の一般事業主行動計画は、常時雇用する労働者が100人を超える事業主に策定・届出の義務がある。",ok:0,why:"正しい(次世代法12条)。"},{t:"次世代法の有効期限は、2035年3月31日まで延長されている。",ok:0,why:"正しい(2026年4月時点)。"},{t:"プラチナくるみん認定を受けた事業主は、一般事業主行動計画の策定・届出が免除される。",ok:0,why:"正しい(次世代法15条の4)。実施状況の公表が必要。"},{t:"女性活躍推進法の一般事業主行動計画は、女性の活躍に関する状況把握・課題分析を行わずに策定することができる。",ok:1,why:"誤り。状況把握・課題分析を行い、その結果を勘案して策定しなければならない(女性活躍推進法8条3項)。"},{t:"女性活躍推進法の一般事業主行動計画は、常時雇用する労働者が100人を超える事業主に策定・届出の義務がある。",ok:0,why:"正しい。2022年4月から101人以上に拡大。"}],memoryPoint:"次世代法・女活法とも行動計画は101人以上が義務。次世代法は2035年まで延長。プラチナ認定で策定・届出が免除。",trap:"状況把握・課題分析の要否、100人・300人の人数要件を入れ替える改変。",e:"女活法の行動計画は状況把握・課題分析が前提(同法8条3項)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-11",s:8,format:"choice",examFmt:true,topic:"職業能力開発促進法",difficulty:3,q:"職業能力開発促進法に関する次の記述のうち、正しいものはどれか。",choices:[{t:"職業能力開発推進者の選任は、事業主の義務である。",ok:0,why:"誤り。努力義務(12条)。"},{t:"認定職業訓練の認定は、厚生労働大臣が行う。",ok:0,why:"誤り。都道府県知事が行う(24条)。"},{t:"技能検定に合格した者は技能士と称することができ、技能士でない者は技能士という名称を用いてはならない。",ok:1,why:"正しい(50条)。"},{t:"キャリアコンサルタントの登録には有効期間の定めがない。",ok:0,why:"誤り。5年ごとの更新制(30条の20)。"},{t:"職業能力開発基本計画は、都道府県知事が策定する。",ok:0,why:"誤り。厚生労働大臣が策定する(5条)。"}],memoryPoint:"推進者は努力義務。認定職業訓練は知事。技能士・キャリアコンサルタントは名称独占、キャリコンは5年更新。",trap:"国と都道府県の役割、義務と努力義務を入れ替える改変。",e:"技能士は名称独占(能開法50条)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-12",s:8,format:"choice",examFmt:true,topic:"中小企業退職金共済法",difficulty:3,q:"中小企業退職金共済法に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"掛金月額は、原則として5,000円以上30,000円以下である。",ok:0,why:"正しい。短時間労働者は2,000円からの特例掛金月額がある。"},{t:"退職金は、独立行政法人勤労者退職金共済機構から被共済者に直接支払われる。",ok:0,why:"正しい。"},{t:"共済契約者は、原則として従業員全員を被共済者としなければならない。",ok:0,why:"正しい。期間を定めて雇用される者等は除くことができる。"},{t:"掛金納付月数が12か月未満の場合、退職金は支給されない。",ok:0,why:"正しい。"},{t:"中小企業退職金共済制度には、事業規模にかかわらずすべての事業主が加入できる。",ok:1,why:"誤り。加入できるのは、業種ごとの常用従業員数又は資本金等の要件を満たす中小企業者に限られる。"}],memoryPoint:"掛金5,000〜30,000円、退職金は本人に直接、原則全員加入、12か月未満は不支給。加入は中小企業者のみ。",trap:"12か月と24か月(元本割れの境目)、中小企業者要件の有無を混同させる改変。",e:"加入できるのは中小企業者に限られる。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-13",s:8,format:"choice",examFmt:true,topic:"国民健康保険法",difficulty:3,q:"国民健康保険法に関する次の記述のうち、正しいものはどれか。",choices:[{t:"国民健康保険組合の設立の認可は、厚生労働大臣が行う。",ok:0,why:"誤り。主たる事務所の所在地の都道府県知事が行う(17条)。"},{t:"国民健康保険の傷病手当金は、市町村が必ず支給しなければならない。",ok:0,why:"誤り。条例・規約で定めて行う任意給付(58条2項)。"},{t:"国民健康保険審査会は都道府県に置かれ、被保険者代表・保険者代表・公益代表の委員各3人で組織される。",ok:1,why:"正しい(92条・93条)。"},{t:"国民健康保険税の徴収権の消滅時効は2年である。",ok:0,why:"誤り。保険税は地方税法により5年。保険料は2年(110条)。"},{t:"世帯主は、被保険者の資格の取得について30日以内に届け出なければならない。",ok:0,why:"誤り。14日以内(施行規則)。"}],memoryPoint:"国保組合の設立は知事の認可。傷病手当金は任意給付。審査会は都道府県・各3人。保険料2年・保険税5年。届出14日。",trap:"保険料と保険税の時効、大臣と知事の取り違え。",e:"国民健康保険審査会は都道府県に置かれ各3人で組織(国保法93条)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-14",s:8,format:"choice",examFmt:true,topic:"高齢者医療確保法",difficulty:3,q:"高齢者の医療の確保に関する法律に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"後期高齢者医療広域連合には、都道府県の区域内のすべての市町村が加入する。",ok:0,why:"正しい(48条)。"},{t:"後期高齢者医療の保険料は、後期高齢者医療広域連合が被保険者から直接徴収する。",ok:1,why:"誤り。保険料を徴収するのは市町村(104条1項)。広域連合は賦課を行う。"},{t:"医療費適正化計画は、6年を1期として定める。",ok:0,why:"正しい(8条・9条)。"},{t:"後期高齢者医療給付等に関する処分に不服がある者は、後期高齢者医療審査会に審査請求をすることができる。",ok:0,why:"正しい(128条)。"},{t:"生活保護法による保護を受けている世帯に属する者は、後期高齢者医療の被保険者とならない。",ok:0,why:"正しい(51条)。"}],memoryPoint:"運営は広域連合(全市町村加入)、保険料の徴収は市町村。適正化計画は6年1期。審査請求は後期高齢者医療審査会。",trap:"賦課(広域連合)と徴収(市町村)を混同させる改変。",e:"後期高齢者医療の保険料は市町村が徴収する(同法104条)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-15",s:8,format:"choice",examFmt:true,topic:"介護保険法",difficulty:3,q:"介護保険法の要介護認定に関する次の記述のうち、正しいものはどれか。",choices:[{t:"要介護認定の効力は、認定を行った日から生ずる。",ok:0,why:"誤り。申請のあった日にさかのぼって効力を生ずる(27条8項)。"},{t:"要介護認定の処分は、申請のあった日から60日以内に行わなければならない。",ok:0,why:"誤り。原則30日以内(27条11項)。"},{t:"介護認定審査会は、都道府県に置かれる。",ok:0,why:"誤り。市町村に置かれる(14条)。都道府県に置かれるのは介護保険審査会。"},{t:"更新認定の有効期間は原則12か月で、3か月から48か月の範囲で定めることができる。",ok:1,why:"正しい(施行規則)。"},{t:"他の市町村に転居した要介護者は、転入先で改めて認定調査と審査判定を受けなければならない。",ok:0,why:"誤り。14日以内に申請すれば審査判定を経ずに認定を受けられる(36条)。"}],memoryPoint:"認定は申請日にさかのぼる。処分は30日以内。認定審査会は市町村、介護保険審査会は都道府県。更新は最長48か月。",trap:"介護認定審査会と介護保険審査会の設置主体を入れ替える改変。",e:"更新認定の有効期間は3〜48か月(施行規則)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-16",s:8,format:"choice",examFmt:true,topic:"介護保険法",difficulty:3,q:"介護保険法の保険給付及び財政に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"第2号被保険者の保険料は、医療保険者が医療保険料と一体で徴収する。",ok:0,why:"正しい。支払基金に介護給付費・地域支援事業支援納付金として納付される。"},{t:"居宅介護サービス計画費には、利用者負担がない。",ok:0,why:"正しい(10割給付)。"},{t:"財政安定化基金は、都道府県が設置する。",ok:0,why:"正しい(147条)。"},{t:"労災保険法等により介護保険の給付に相当する給付を受けられるときは、その限度で介護保険の給付は行われない。",ok:0,why:"正しい(20条)。"},{t:"第2号被保険者で一定以上の所得がある者は、利用者負担が2割又は3割となる。",ok:1,why:"誤り。2割・3割負担は第1号被保険者の一定以上所得者が対象。第2号被保険者は1割。"}],memoryPoint:"第2号保険料は医療保険者が一体徴収。ケアプランは10割給付。財政安定化基金は都道府県。2割・3割負担は第1号のみ。",trap:"2割・3割負担の対象を第2号被保険者にまで広げる改変。",e:"第2号被保険者の利用者負担は所得にかかわらず1割。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-17",s:8,format:"choice",examFmt:true,topic:"確定給付企業年金法",difficulty:3,q:"確定給付企業年金法に関する次の記述のうち、正しいものはどれか。",choices:[{t:"規約型企業年金の規約は、厚生労働大臣の認可を受けなければならない。",ok:0,why:"誤り。規約は「承認」(3条)。基金の設立が「認可」(4条)。"},{t:"規約において、20年を超える加入者期間を老齢給付金の支給要件として定めてはならない。",ok:1,why:"正しい(36条4項)。"},{t:"年金給付の支給期間は、終身又は10年以上でなければならない。",ok:0,why:"誤り。終身又は5年以上(33条)。"},{t:"掛金の額は、少なくとも3年ごとに再計算しなければならない。",ok:0,why:"誤り。少なくとも5年ごと(58条)。"},{t:"遺族給付金は、必ず支給しなければならない給付である。",ok:0,why:"誤り。規約で定めた場合に行う任意の給付(29条2項)。"}],memoryPoint:"規約型は承認・基金は認可。老齢は20年超の要件不可、脱退一時金は3年超の要件不可。年金は終身か5年以上。再計算は5年ごと。",trap:"承認と認可、5年と10年など数字の入替え。",e:"老齢給付金の要件に20年を超える加入者期間は不可(DB法36条4項)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-18",s:8,format:"choice",examFmt:true,topic:"確定拠出年金法",difficulty:3,q:"企業型確定拠出年金に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"企業型年金加入者の資格は、70歳未満の厚生年金保険の被保険者に認められる(規約で一定の資格を定めることは可)。",ok:0,why:"正しい(2022年5月〜)。"},{t:"運営管理機関は、35本以下の範囲で、リスク・リターン特性の異なる3以上の運用の方法を提示する。",ok:0,why:"正しい(23条)。"},{t:"事業主掛金相当分の返還を規約で定めることができるのは、勤続期間5年未満の者が資格を喪失した場合である。",ok:1,why:"誤り。勤続期間3年未満の者(3条3項)。"},{t:"他の企業年金制度を実施していない場合の拠出限度額は、月額55,000円である。",ok:0,why:"正しい。"},{t:"事業主は、加入者等に対する投資教育を継続的に行うよう努めなければならない。",ok:0,why:"正しい(22条)。"}],memoryPoint:"企業型加入は70歳未満。運用商品は3以上35以下。掛金返還は勤続3年未満。限度額55,000円。投資教育は努力義務。",trap:"返還対象の3年を5年に変える改変。DBの脱退一時金の3年とあわせて覚える。",e:"事業主掛金の返還は勤続3年未満の者に限る(DC法3条3項)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-19",s:8,format:"choice",examFmt:true,topic:"確定拠出年金法",difficulty:3,q:"個人型確定拠出年金(iDeCo)に関する次の記述のうち、正しいものはどれか。",choices:[{t:"個人型確定拠出年金は、企業年金連合会が実施する。",ok:0,why:"誤り。国民年金基金連合会が実施する(55条)。"},{t:"国民年金の第1号被保険者の拠出限度額は、国民年金基金の掛金とは別枠で月額68,000円である。",ok:0,why:"誤り。国民年金基金の掛金・付加保険料と合算して月額68,000円。"},{t:"企業年金等に加入していない会社員と第3号被保険者の拠出限度額は、いずれも月額23,000円である。",ok:1,why:"正しい。"},{t:"老齢給付金の受給は、70歳に達するまでに開始しなければならない。",ok:0,why:"誤り。75歳に達するまで(2022年4月〜)。"},{t:"中小事業主掛金納付制度(iDeCo+)は、企業型確定拠出年金を実施している事業主が利用する制度である。",ok:0,why:"誤り。企業年金を実施していない300人以下の事業主が対象(68条の2)。"}],memoryPoint:"実施者は国民年金基金連合会。第1号は基金と合算68,000円、企業年金なしの会社員と第3号は23,000円。受給開始は75歳まで。",trap:"国民年金基金連合会と企業年金連合会の取り違え、別枠・合算の入替え。",e:"企業年金なしの第2号と第3号は月額23,000円。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-20",s:8,format:"choice",examFmt:true,topic:"児童手当法",difficulty:3,q:"児童手当法に関する次の記述のうち、誤っているものはどれか(2026年4月時点)。",choices:[{t:"児童とは、18歳に達する日以後の最初の3月31日までの間にある者をいう。",ok:0,why:"正しい(3条1項)。"},{t:"児童手当の支払期月は、偶数月の年6回である。",ok:0,why:"正しい(2024年10月改正)。"},{t:"第3子以降の児童手当の額は、年齢を問わず月額30,000円である。",ok:0,why:"正しい。"},{t:"公務員である受給資格者の認定は、住所地の市町村長が行う。",ok:1,why:"誤り。所属庁の長等が行う(17条)。"},{t:"受給資格者が出生の日の翌日から15日以内に認定の請求をしたときは、出生の日の属する月の翌月から支給される。",ok:0,why:"正しい(8条3項)。"}],memoryPoint:"児童は18歳年度末まで。支払は偶数月の年6回。第3子以降3万円。公務員は所属庁。15日特例。",trap:"公務員の認定機関、支払回数(年3回→年6回)の新旧を混同させる改変。",e:"公務員の認定は所属庁の長等(児童手当法17条)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-21",s:8,format:"choice",examFmt:true,topic:"社会保険審査官及び社会保険審査会法",difficulty:3,q:"社会保険審査官及び社会保険審査会法に関する次の記述のうち、正しいものはどれか。",choices:[{t:"社会保険審査官に対する審査請求は、原処分があったことを知った日の翌日から起算して60日以内にしなければならない。",ok:0,why:"誤り。3か月以内(4条1項)。"},{t:"社会保険審査会への再審査請求は、決定書の謄本が送付された日の翌日から起算して3か月以内にしなければならない。",ok:0,why:"誤り。2か月以内(32条1項)。"},{t:"社会保険審査会は、委員長及び委員3人をもって組織する。",ok:0,why:"誤り。委員長及び委員5人(19条)。"},{t:"審査請求があったときは、原処分の執行は当然に停止される。",ok:0,why:"誤り。執行は停止されない。審査官が必要と認めるときは停止できる(10条)。"},{t:"健康保険の保険料等の賦課又は徴収の処分に不服がある者は、直接社会保険審査会に審査請求をすることができる。",ok:1,why:"正しい(健康保険法190条)。"}],memoryPoint:"審査請求3か月、再審査請求2か月。審査会は委員長+委員5人。執行不停止。保険料の賦課・徴収処分は審査会へ直接。",trap:"3か月と2か月、二審制と一審制の区別を入れ替える改変。",e:"保険料等の賦課・徴収処分は社会保険審査会へ直接審査請求(健保法190条)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-22",s:8,format:"choice",examFmt:true,topic:"社会保険労務士法",difficulty:3,q:"社会保険労務士法に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"社会保険労務士は、裁判所において、補佐人として弁護士である訴訟代理人とともに出頭し、陳述をすることができる。",ok:0,why:"正しい(2条の2)。"},{t:"社会保険労務士法人は、社員が1人でも設立することができる。",ok:0,why:"正しい(2016年1月〜)。"},{t:"開業社会保険労務士は、業務に関する帳簿を帳簿閉鎖の時から5年間保存しなければならない。",ok:1,why:"誤り。2年間(19条)。"},{t:"特定社会保険労務士は、都道府県労働委員会が行う個別労働関係紛争のあっせんの手続について、当事者を代理することができる。",ok:0,why:"正しい(2条1項1号の5)。"},{t:"民間紛争解決手続の代理は、紛争の目的の価額が120万円を超える場合には、弁護士が同一の依頼者から受任しているものに限られる。",ok:0,why:"正しい(2条1項1号の6)。"}],memoryPoint:"補佐人制度あり。1人法人可。帳簿は2年保存。特定社労士は労働委員会のあっせんも代理可。民間ADRは120万円が境目。",trap:"帳簿保存期間を2年から5年にずらす改変。",e:"帳簿の保存期間は2年(社労士法19条)。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-23",s:8,format:"choice",examFmt:true,topic:"船員保険法",difficulty:3,q:"船員保険法に関する次の記述のうち、正しいものはどれか。",choices:[{t:"船員保険の保険者は国であり、厚生労働大臣が管掌する。",ok:0,why:"誤り。全国健康保険協会(4条)。"},{t:"船員保険の被保険者は、日本国籍を有する船員に限られる。",ok:0,why:"誤り。国籍要件はない(2条)。"},{t:"被保険者が職務上の事由により1か月以上行方不明となったときは、被扶養者に行方不明手当金が支給される。",ok:1,why:"正しい。支給期間は3か月が限度。"},{t:"疾病任意継続被保険者となるには、資格喪失日の前日まで継続して1年以上被保険者であったことが必要である。",ok:0,why:"誤り。継続して2か月以上(2条2項)。"},{t:"船員保険協議会は、厚生労働省に置かれる。",ok:0,why:"誤り。全国健康保険協会に置かれる(6条)。"}],memoryPoint:"保険者は協会、協議会も協会に置く。国籍要件なし。行方不明手当金は1か月以上の行方不明で3か月まで。任意継続は2か月以上。",trap:"保険者・協議会の所在を国に付け替える改変。",e:"行方不明手当金は船員保険独自の給付。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT8-24",s:8,format:"choice",examFmt:true,topic:"沿革",difficulty:2,q:"社会保険制度の沿革に関する次の記述のうち、正しいものはどれか。",choices:[{t:"健康保険法は、1947年(昭和22年)に労働基準法と同時に制定された。",ok:0,why:"誤り。1922年(大正11年)制定、1927年(昭和2年)全面施行。"},{t:"介護保険法は1997年(平成9年)に制定され、2000年(平成12年)4月に施行された。",ok:1,why:"正しい。"},{t:"国民皆保険・皆年金は、1973年(昭和48年)に実現した。",ok:0,why:"誤り。1961年(昭和36年)4月に実現。"},{t:"後期高齢者医療制度は、1983年(昭和58年)に創設された。",ok:0,why:"誤り。1983年は老人保健法の施行。後期高齢者医療制度は2008年(平成20年)4月。"},{t:"児童手当法は、2000年(平成12年)に制定された。",ok:0,why:"誤り。1971年(昭和46年)制定、1972年施行。"}],memoryPoint:"健保1922、旧国保1938、皆保険・皆年金1961、児童手当1971、老人保健法1982制定、介護保険2000、後期高齢者2008。",trap:"年号を別の制度の出来事とすり替える改変。",e:"介護保険法は1997年制定・2000年4月施行。",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS8-1",s:8,format:"sentaku",sentaku:true,topic:"労働者派遣法",difficulty:3,q:"【選択式】労働者派遣法 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"労働者派遣法によれば、派遣先は、当該派遣先の事業所その他派遣就業の場所ごとの業務について、派遣元事業主から[[A]]を超える期間継続して労働者派遣の役務の提供を受けてはならない。派遣先が当該期間を延長しようとするときは、抵触日の[[B]]前の日までの間に、当該事業所の過半数労働組合等の意見を聴かなければならない。派遣先が期間制限に違反して労働者派遣の役務の提供を受けた場合には、その時点において、派遣先が当該派遣労働者に対し、その時点における労働条件と同一の労働条件を内容とする[[C]]をしたものとみなされる(善意無過失の場合を除く)。また、派遣元事業主は、派遣先を離職した後[[D]]を経過しない者(60歳以上の定年退職者を除く)を当該派遣先に派遣してはならない。派遣元事業主が関係派遣先に労働者派遣をするときは、関係派遣先への派遣割合を100分の[[E]]以下としなければならない。",blanks:[{key:"A",ok:4,why:"事業所単位の派遣可能期間は原則3年。個人単位でも同一組織単位で3年が上限。",law:"労働者派遣法40条の2第1項・40条の3"},{key:"B",ok:11,why:"延長の意見聴取は抵触日の1か月前の日まで。異議があれば延長理由等の説明が必要。",law:"労働者派遣法40条の2第4項"},{key:"C",ok:7,why:"違法派遣の受入れで派遣先が労働契約の申込みをしたものとみなされる(労働契約申込みみなし制度)。",law:"労働者派遣法40条の6"},{key:"D",ok:13,why:"離職後1年以内の者の元の勤務先への派遣は禁止。60歳以上の定年退職者は例外。",law:"労働者派遣法40条の9・35条の5"},{key:"E",ok:3,why:"グループ企業内派遣は8割以下。定年退職者は割合計算から除かれる。",law:"労働者派遣法23条の2"}],options:["4年","2週間","90","80","3年","6か月","雇用の承諾","労働契約の申込み","100","5年","10日","1か月","2年","1年","労働契約の締結","採用の内定","60","3か月","70","50"],memoryPoint:"派遣可能期間3年・延長の意見聴取は1か月前・違法派遣は申込みみなし・離職後1年は派遣禁止・グループ内派遣は8割以下。",trap:"申込みみなしは「締結」とみなすのではなく「申込み」とみなす点が狙われる。数字は3年・1か月・1年・80の組合せ。",e:"派遣可能期間3年、意見聴取は抵触日1か月前、違法派遣は労働契約の申込みみなし、離職後1年以内の派遣禁止、グループ内8割以下。",source:"労働者派遣法23条の2・35条の5・40条の2・40条の6・40条の9",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS8-2",s:8,format:"sentaku",sentaku:true,topic:"高年齢者雇用安定法",difficulty:3,q:"【選択式】高年齢者雇用安定法 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"高年齢者雇用安定法によれば、事業主がその雇用する労働者の定年の定めをする場合には、当該定年は、[[A]]を下回ることができない。65歳未満の定年の定めをしている事業主は、当該定年の引上げ、[[B]]の導入又は当該定年の定めの廃止のいずれかの措置を講じなければならない。また、65歳以上70歳未満の定年の定めをしている事業主等は、70歳までの安定した就業を確保するための措置を講ずることにより、65歳から70歳までの就業機会を確保するよう[[C]]。事業主は、解雇等により離職することとなっている高年齢者等が希望するときは、[[D]]を作成し、当該高年齢者等に交付しなければならない。さらに、事業主は、1か月以内に[[E]]以上の高年齢者等が解雇等により離職する場合には、あらかじめ公共職業安定所長に届け出なければならない。",blanks:[{key:"A",ok:16,why:"定年は60歳以上。坑内作業の業務に従事する労働者は例外。",law:"高年法8条"},{key:"B",ok:9,why:"65歳までの雇用確保措置は、定年の引上げ・継続雇用制度の導入・定年の廃止の3つ。",law:"高年法9条1項"},{key:"C",ok:8,why:"70歳までの就業確保措置は努力義務。65歳までの雇用確保措置は義務。",law:"高年法10条の2"},{key:"D",ok:7,why:"45歳以上70歳未満の離職予定者が希望すれば作成・交付が義務。",law:"高年法17条"},{key:"E",ok:19,why:"多数離職届は5人以上。労働施策総合推進法の大量雇用変動届は30人以上。",law:"高年法16条"}],options:["勤務延長制度","再雇用契約","ジョブ・カード","30人","再就職援助計画","65歳","70歳","求職活動支援書","努めなければならない","継続雇用制度","3人","就業規則","10人","100人","職務経歴書","配慮しなければならない","60歳","55歳","しなければならない","5人"],memoryPoint:"定年60歳以上、65歳まで義務(3措置)、70歳まで努力義務、求職活動支援書、多数離職届は5人。",trap:"65歳までは「しなければならない」、70歳までは「努めなければならない」。5人と30人の混同にも注意。",e:"定年60歳、雇用確保措置(継続雇用制度等)、70歳就業確保は努力義務、求職活動支援書、多数離職届5人。",source:"高年法8条・9条・10条の2・16条・17条",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS8-3",s:8,format:"sentaku",sentaku:true,topic:"育児・介護休業法",difficulty:3,q:"【選択式】育児・介護休業法 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"育児・介護休業法によれば、出生時育児休業(産後パパ育休)は、子の出生の日から起算して[[A]]を経過する日の翌日までの期間内に、4週間以内の期間を定めて取得することができる。介護休業は、対象家族1人につき、通算して[[B]]まで、3回を上限として分割して取得することができる。事業主は、小学校就学の始期に達するまでの子を養育する労働者が請求した場合には、事業の正常な運営を妨げる場合を除き、1か月について[[C]]、1年について150時間を超える時間外労働をさせてはならない。深夜業の制限の請求は、1回につき1か月以上[[D]]以内の期間について行う。また、事業主は、労働者から本人又は配偶者が妊娠し又は出産したこと等の申出があったときは、育児休業に関する制度等を[[E]]とともに、休業の取得の意向を確認するための面談等の措置を講じなければならない。",blanks:[{key:"A",ok:2,why:"産後パパ育休は出生後8週間以内に4週間まで、2回に分割可。",law:"育介法9条の2"},{key:"B",ok:11,why:"介護休業は通算93日・3回まで分割可。",law:"育介法11条2項"},{key:"C",ok:5,why:"時間外労働の制限は月24時間・年150時間。要介護家族の介護者も同じ。",law:"育介法17条"},{key:"D",ok:9,why:"深夜業の制限は1回1か月以上6か月以内。所定外・時間外の制限は1か月以上1年以内。",law:"育介法19条"},{key:"E",ok:10,why:"妊娠・出産等の申出時の個別周知・意向確認は義務。取得を控えさせる方法は不可。",law:"育介法21条1項"}],options:["書面で公表する","36時間","8週間","45時間","30日","24時間","就業規則に記載する","3か月","12時間","6か月","個別に周知する","93日","2週間","60日","事業所内に掲示する","1年","180日","6週間","労働組合に通知する","12週間"],memoryPoint:"産後パパ育休は8週間以内に4週間、介護休業93日・3回、時間外制限は月24時間・年150時間、深夜業制限は6か月以内、申出時は個別周知と意向確認。",trap:"深夜業の制限(6か月以内)と所定外・時間外の制限(1年以内)の期間を入れ替える形が定番。",e:"8週間・93日・24時間・6か月・個別周知。",source:"育介法9条の2・11条・17条・19条・21条",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS8-4",s:8,format:"sentaku",sentaku:true,topic:"労働組合法",difficulty:3,q:"【選択式】労働組合法 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"労働組合法によれば、使用者が、雇用する労働者の代表者と[[A]]をすることを正当な理由がなくて拒むことや、労働組合の運営のための経費の支払につき[[B]]を与えることは、不当労働行為として禁止される。労働委員会は、不当労働行為の救済の申立てが、行為の日(継続する行為にあってはその終了した日)から[[C]]を経過した事件に係るものであるときは、これを受けることができない。労働協約には、[[D]]を超える有効期間の定めをすることができず、これを超える定めをしたときは、その上限の期間を有効期間として定めたものとみなされる。一の工場事業場に常時使用される同種の労働者の[[E]]以上の数の労働者が一の労働協約の適用を受けるに至ったときは、当該工場事業場に使用される他の同種の労働者に関しても、当該労働協約が適用される。",blanks:[{key:"A",ok:6,why:"正当な理由のない団体交渉拒否は7条2号の不当労働行為。",law:"労組法7条2号"},{key:"B",ok:12,why:"経費援助は支配介入とともに7条3号。勤務時間中の協議交渉の許容や最小限の事務所の供与は除外。",law:"労組法7条3号"},{key:"C",ok:2,why:"救済申立ては行為の日(継続する行為は終了日)から1年以内。",law:"労組法27条2項"},{key:"D",ok:5,why:"3年を超える定めは3年の有効期間を定めたものとみなされる。",law:"労組法15条1項・2項"},{key:"E",ok:10,why:"工場事業場単位の一般的拘束力は同種の労働者の4分の3以上。地域単位は「大部分」+決定手続。",law:"労組法17条"}],options:["過半数","5年","1年","5分の4","3分の2","3年","団体交渉","苦情処理","事務所の供与","大部分","4分の3","便宜供与","経理上の援助","10年","労使協議","6か月","労働協約の締結","2年","3か月","3分の1"],memoryPoint:"団交拒否・経費援助は不当労働行為。救済申立ては1年以内。協約の有効期間は最長3年。事業場単位の拡張適用は4分の3以上。",trap:"事業場単位(17条・4分の3)と地域単位(18条・大部分)の取り違えが定番。",e:"団体交渉拒否・経理上の援助の禁止、申立て1年、協約は最長3年、一般的拘束力4分の3。",source:"労組法7条・15条・17条・27条",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS8-5",s:8,format:"sentaku",sentaku:true,topic:"国民健康保険法",difficulty:3,q:"【選択式】国民健康保険法 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"国民健康保険法によれば、都道府県は、当該都道府県内の市町村とともに国民健康保険を行うものとされ、安定的な財政運営、市町村の国民健康保険事業の効率的な実施の確保その他の都道府県及び当該都道府県内の市町村の国民健康保険事業の健全な運営について[[A]]的な役割を果たすものとされる。都道府県の区域内に住所を有する者は、適用除外に該当する者を除き、当該都道府県が当該都道府県内の市町村とともに行う国民健康保険の被保険者とされる。適用除外には、健康保険等の被用者保険の被保険者・被扶養者、後期高齢者医療の被保険者のほか、[[B]]による保護を受けている世帯に属する者などがある。国民健康保険組合を設立しようとするときは、主たる事務所の所在地の[[C]]の認可を受けなければならない。市町村及び国民健康保険組合は、条例又は規約の定めるところにより出産育児一時金の支給及び葬祭費の支給又は葬祭の給付を行うものとするが、[[D]]があるときは、その全部又は一部を行わないことができる。保険給付に関する処分や保険料等に関する処分に不服がある者は、[[E]]に審査請求をすることができる。",blanks:[{key:"A",ok:7,why:"平成30年度から都道府県が財政運営の責任主体として中心的な役割を担う。",law:"国保法4条2項"},{key:"B",ok:15,why:"保護を受けている世帯(停止中を除く)は適用除外。医療は医療扶助による。",law:"国保法6条9号"},{key:"C",ok:12,why:"国保組合の設立は組合員となる者300人以上の同意を得て知事の認可。",law:"国保法17条"},{key:"D",ok:17,why:"出産育児一時金・葬祭費は相対的必要給付。特別の理由があれば行わないことができる。",law:"国保法58条1項"},{key:"E",ok:1,why:"都道府県に置かれ、被保険者代表・保険者代表・公益代表各3人で組織。",law:"国保法91条・92条"}],options:["補完","国民健康保険審査会","調整","財政上の理由","市町村長","厚生労働大臣","介護保険審査会","中心","児童福祉法","社会保険審査会","やむを得ない事由","国民健康保険団体連合会","都道府県知事","障害者総合支援法","主導","生活保護法","正当な理由","特別の理由","社会保険審査官","地方厚生局長"],memoryPoint:"都道府県は中心的役割、生活保護世帯は適用除外、組合設立は知事認可、出産育児一時金・葬祭費は特別の理由で不実施可、審査請求は国保審査会。",trap:"国保の不服申立ては社会保険審査官・審査会ではなく国民健康保険審査会。組合設立の認可権者は大臣ではなく知事。",e:"中心的役割・生活保護法・都道府県知事・特別の理由・国民健康保険審査会。",source:"国保法4条・6条・17条・58条・91条",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS8-6",s:8,format:"sentaku",sentaku:true,topic:"介護保険法",difficulty:3,q:"【選択式】介護保険法 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"介護保険法によれば、市町村及び特別区は介護保険を行う。市町村の区域内に住所を有する40歳以上[[A]]未満の医療保険加入者は第2号被保険者となる。要介護認定の申請に対する処分は、原則として申請のあった日から[[B]]以内にしなければならず、要介護認定はその申請のあった日にさかのぼってその効力を生ずる。市町村は、基本指針に即して、[[C]]年を1期とする市町村介護保険事業計画を定める。保険料その他の徴収金を徴収し又はその還付を受ける権利及び保険給付を受ける権利は、これらを行使することができる時から[[D]]を経過したときは、時効によって消滅する。保険給付に関する処分又は保険料その他の徴収金に関する処分に不服がある者は、都道府県に置かれる[[E]]に審査請求をすることができる。",blanks:[{key:"A",ok:13,why:"第1号は65歳以上、第2号は40歳以上65歳未満の医療保険加入者。",law:"介護保険法9条"},{key:"B",ok:7,why:"処分は原則30日以内。特別な理由があれば延期できる。",law:"介護保険法27条11項"},{key:"C",ok:10,why:"市町村介護保険事業計画・都道府県介護保険事業支援計画はいずれも3年1期。",law:"介護保険法117条"},{key:"D",ok:11,why:"介護保険の時効は2年。",law:"介護保険法200条1項"},{key:"E",ok:15,why:"都道府県に置かれる。市町村に置かれる介護認定審査会と区別する。",law:"介護保険法183条・184条"}],options:["介護認定審査会","社会保険審査会","5年","国民健康保険審査会","5","2","3年","30日","70歳","90日","3","2年","75歳","65歳","14日","介護保険審査会","60歳","60日","1年","6"],memoryPoint:"第2号は40歳以上65歳未満、認定処分は30日以内、事業計画は3年1期、時効2年、審査請求は介護保険審査会(都道府県)。",trap:"介護認定審査会(市町村・認定の審査判定)と介護保険審査会(都道府県・審査請求)の取り違えが定番。",e:"65歳・30日・3年・2年・介護保険審査会。",source:"介護保険法9条・27条・117条・183条・200条",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS8-7",s:8,format:"sentaku",sentaku:true,topic:"確定給付企業年金法・確定拠出年金法",difficulty:3,q:"【選択式】確定給付企業年金法・確定拠出年金法 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"確定給付企業年金法によれば、老齢給付金は、[[A]]歳以上70歳以下の規約で定める年齢に達したとき等に支給するものでなければならず、規約において[[B]]を超える加入者期間を老齢給付金の給付を受けるための要件として定めてはならない。年金給付の支給期間は、終身又は[[C]]以上にわたり、毎年1回以上定期的に支給するものでなければならない。確定拠出年金法によれば、個人型年金は[[D]]が実施する。また、企業型年金において事業主掛金相当分の返還を規約で定めることができるのは、勤続期間が[[E]]未満の企業型年金加入者が資格を喪失した場合である。",blanks:[{key:"A",ok:0,why:"老齢給付金は60歳以上70歳以下の規約で定める年齢到達時等(50歳以上で退職した場合も可)。",law:"確定給付企業年金法36条2項"},{key:"B",ok:14,why:"20年を超える加入者期間を老齢給付金の要件とすることはできない。",law:"確定給付企業年金法36条4項"},{key:"C",ok:16,why:"年金は終身又は5年以上、毎年1回以上定期的に支給。",law:"確定給付企業年金法33条"},{key:"D",ok:3,why:"個人型年金(iDeCo)の実施者。企業型は事業主が実施。",law:"確定拠出年金法55条"},{key:"E",ok:13,why:"勤続3年未満の者について、事業主掛金相当分の返還を規約で定められる。",law:"確定拠出年金法3条3項"}],options:["60","日本年金機構","50","国民年金基金連合会","1年","2年","6年","30年","全国健康保険協会","企業年金連合会","15年","65","10年","3年","20年","運営管理機関","5年","70","55","25年"],memoryPoint:"DB老齢は60〜70歳・20年超の要件不可・年金は終身又は5年以上。iDeCoは国民年金基金連合会。DC掛金返還は勤続3年未満。",trap:"企業年金連合会(ポータビリティの受け皿)と国民年金基金連合会(iDeCo実施者)の取り違えが定番。",e:"60・20年・5年・国民年金基金連合会・3年。",source:"確定給付企業年金法33条・36条、確定拠出年金法3条・55条",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS8-8",s:8,format:"sentaku",sentaku:true,topic:"社会保険労務士法",difficulty:3,q:"【選択式】社会保険労務士法 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"社会保険労務士法によれば、紛争解決手続代理業務は、[[A]]に限り行うことができる。民間紛争解決手続における代理は、紛争の目的の価額が[[B]]を超える場合には、弁護士が同一の依頼者から受任しているものに限られる。社会保険労務士は、事業における労務管理その他の労働に関する事項及び労働社会保険諸法令に基づく社会保険に関する事項について、裁判所において、[[C]]として、弁護士である訴訟代理人とともに出頭し、陳述をすることができる。開業社会保険労務士は、その業務に関する帳簿を備え、帳簿閉鎖の時から[[D]]間、関係書類とともに保存しなければならない。社会保険労務士に対する懲戒処分は、戒告、[[E]]以内の業務の停止及び失格処分の3種とされる。",blanks:[{key:"A",ok:0,why:"紛争解決手続代理業務試験に合格し、その旨の付記を受けた社会保険労務士に限られる。",law:"社労士法2条2項"},{key:"B",ok:17,why:"民間ADRの単独代理は120万円まで。超える場合は弁護士との共同受任。",law:"社労士法2条1項1号の6"},{key:"C",ok:13,why:"2015年4月施行の補佐人制度。",law:"社労士法2条の2"},{key:"D",ok:14,why:"帳簿の保存期間は2年。",law:"社労士法19条"},{key:"E",ok:5,why:"懲戒は戒告・1年以内の業務停止・失格処分の3種で、処分は厚生労働大臣が行う。",law:"社労士法25条"}],options:["特定社会保険労務士","特別代理人","140万円","開業社会保険労務士","3か月","1年","5年","100万円","訴訟代理人","10年","7年","社会保険労務士法人","60万円","補佐人","2年","3年","全国社会保険労務士会連合会","120万円","6か月","参考人"],memoryPoint:"代理は特定社労士のみ、民間ADRは120万円、裁判所では補佐人、帳簿は2年保存、懲戒の業務停止は1年以内。",trap:"補佐人は訴訟代理人ではない。120万円は簡易裁判所の訴額上限(140万円)と混同させる改変が狙われる。",e:"特定社会保険労務士・120万円・補佐人・2年・1年。",source:"社労士法2条・2条の2・19条・25条",lawAsOf:"2026-04-01",examYear:2026}
);
